# -*- coding: utf-8 -*-
# domain_profiles.py - 37 non-IT domain profiles

DOMAIN_PROFILES = {'Kế toán': {'discipline': 'kế toán tài chính, chuẩn mực kế toán VAS/IFRS, hạch toán kế toán, kiểm toán nội bộ và báo cáo thuế doanh nghiệp', 'intro': 'Kế toán là ngôn ngữ của kinh doanh, giữ vai trò huyết mạch trong việc phản ánh trung thực tình hình tài chính, kết quả kinh doanh và dòng tiền của mọi tổ chức kinh tế. Một người làm kế toán chuyên nghiệp không chỉ đơn thuần là người ghi chép sổ sách mà là người gác cổng tài chính, giúp lãnh đạo đưa ra các quyết định chiến lược dựa trên những con số minh bạch và tuân thủ pháp luật.', 'beginner': 'Đối với người mới bắt đầu, điều cốt tử là nắm vững nguyên tắc ghi sổ kép Nợ - Có, hiểu bản chất các mối quan hệ đối ứng tài khoản và quy trình luân chuyển chứng từ gốc trước khi sử dụng các phần mềm kế toán tự động.', 'tools': ['Phần mềm kế toán MISA SME / AMIS', 'Microsoft Excel kế toán chuyên sâu', 'Phần mềm Hỗ trợ kê khai thuế (HTKK)', 'Hệ thống hóa đơn điện tử'], 'standards': ['Thông tư 200/2014/TT-BTC', 'Chuẩn mực kế toán Việt Nam (VAS)', 'Chuẩn mực báo cáo tài chính quốc tế (IFRS)', 'Luật Quản lý thuế'], 'roles': {1: [('Kế toán viên tập sự (Accounting Intern)', 'Hỗ trợ phân loại, kiểm tra tính hợp lệ của chứng từ gốc và ghi chép sổ sách ban đầu.'), ('Nhân viên kiểm tra chứng từ & Lưu trữ', 'Sắp xếp hóa đơn, đối chiếu phiếu thu - chi và quản lý hồ sơ chứng từ kế toán.'), ('Cộng tác viên nhập liệu kế toán', 'Nhập liệu hóa đơn đầu vào, đầu ra vào phần mềm kế toán dưới sự giám sát của kế toán trưởng.')], 2: [('Chuyên viên kế toán phần hành (Junior Accountant)', 'Đảm nhận kế toán mua hàng, bán hàng, tiền lương và bảo hiểm xã hội.'), ('Kế toán viên kho & Công nợ', 'Theo dõi nhập - xuất - tồn kho vật tư, đối chiếu công nợ phải thu, phải trả với khách hàng và nhà cung cấp.'), ('Trợ lý kiểm toán nội bộ tập sự', 'Hỗ trợ kiểm kê tài sản định kỳ và rà soát tính tuân thủ quy trình chi tiêu nội bộ.')], 3: [('Kế toán tổng hợp (General Accountant)', 'Kiểm tra định khoản, hạch toán các bút toán cuối kỳ, trích khấu hao tài sản và kết chuyển doanh thu - chi phí.'), ('Chuyên viên kế toán thuế & Quyết toán', 'Lập tờ khai thuế GTGT, TNCN, tạm tính thuế TNDN và chuẩn bị hồ sơ quyết toán thuế định kỳ.'), ('Trợ lý kiểm toán độc lập (Audit Assistant)', 'Tham gia nhóm kiểm toán Báo cáo tài chính tại khách hàng, kiểm tra số dư và lập giấy làm việc kiểm toán.')], 4: [('Kế toán viên cao cấp / Kế toán tổng hợp chính thức', 'Chịu trách nhiệm lập trọn bộ Báo cáo tài chính chuẩn VAS và giải trình số liệu với cơ quan thuế.'), ('Chuyên viên tư vấn tài chính & Thuế (Tax Consultant)', 'Tư vấn tối ưu hóa chi phí thuế hợp pháp và lập kế hoạch thuế cho doanh nghiệp.'), ('Kiểm toán viên độc lập (Associate Auditor)', 'Thực hiện kiểm toán các phần hành trọng yếu và đóng góp vào Báo cáo kiểm toán độc lập.')]}}, 'Tài chính - Ngân hàng': {'discipline': 'quản trị tài chính doanh nghiệp, thị trường tiền tệ và vốn, thẩm định tín dụng ngân hàng thương mại, định giá chứng khoán và quản trị rủi ro', 'intro': 'Tài chính - Ngân hàng là huyết mạch phân bổ vốn của toàn bộ nền kinh tế, quyết định sự luân chuyển và sinh lời của dòng tiền giữa người có vốn và người cần vốn. Trong bối cảnh thị trường tài chính hội nhập sâu rộng, việc làm chủ các công cụ mô hình hóa tài chính, kỹ năng đọc vị báo cáo tài chính và năng lực thẩm định rủi ro là vũ khí cạnh tranh mạnh mẽ nhất.', 'beginner': 'Người mới bắt đầu cần làm quen với giá trị thời gian của tiền tệ (TVM), nắm chắc mối quan hệ giữa rủi ro và lợi nhuận (Risk-Return Tradeoff), và rèn luyện kỹ năng xây dựng mô hình tài chính trên Excel chuẩn mực.', 'tools': ['Microsoft Excel tài chính (DCF, NPV, IRR)', 'Phần mềm giao dịch chứng khoán (FiinPro, Vietstock)', 'Hệ thống Core Banking mô phỏng', 'Power BI tài chính'], 'standards': ['Hiệp ước vốn Basel II / Basel III', 'Luật Các tổ chức tín dụng', 'Chuẩn mực thẩm định giá', 'Khung quản trị rủi ro CAMELS'], 'roles': {1: [('Thực tập sinh tài chính cơ sở (Finance Intern)', 'Hỗ trợ thu thập số liệu tài chính công ty niêm yết, nhập liệu bảng tính và tính toán các chỉ số cơ bản.'), ('Cộng tác viên hỗ trợ tín dụng', 'Hỗ trợ kiểm tra hồ sơ khách hàng, phân loại chứng từ pháp lý và nhập liệu thông tin vay vốn.'), ('Trợ lý phân tích thị trường tài chính', 'Tổng hợp tin tức thị trường tiền tệ, lãi suất và biến động tỷ giá hàng tuần.')], 2: [('Chuyên viên quan hệ khách hàng cá nhân (Retail RM)', 'Tư vấn sản phẩm huy động vốn, cho vay tiêu dùng và phát hành thẻ tín dụng tại ngân hàng.'), ('Chuyên viên phân tích tín dụng tập sự (Credit Analyst Trainee)', 'Thẩm định năng lực tài chính của khách hàng vay vốn, tính toán khả năng trả nợ và định giá tài sản đảm bảo.'), ('Trợ lý môi giới chứng khoán (Broker Assistant)', 'Mở tài khoản giao dịch, hướng dẫn khách hàng sử dụng bảng giá và cập nhật thông tin khuyến nghị đầu tư.')], 3: [('Chuyên viên phân tích đầu tư (Investment Analyst)', 'Phân tích ngành, định giá cổ phiếu bằng phương pháp DCF/P/E và viết báo cáo khuyến nghị đầu tư.'), ('Chuyên viên thẩm định tín dụng doanh nghiệp (Corporate Credit Analyst)', 'Thẩm định các dự án vay vốn trung - dài hạn, phân tích dòng tiền dự án và cơ cấu bảo đảm nợ.'), ('Chuyên viên quản trị rủi ro tài chính (Risk Specialist)', 'Đo lường rủi ro thanh khoản, rủi ro tín dụng và kiểm tra sức chịu đựng (Stress Testing) danh mục vốn.')], 4: [('Chuyên viên phân tích tài chính cao cấp (Senior Financial Analyst)', 'Xây dựng mô hình tài chính dự báo ngân sách, đánh giá hiệu quả dự án đầu tư M&A.'), ('Chuyên viên quản lý danh mục đầu tư (Portfolio Analyst)', 'Phân bổ tài sản chiến lược, tái cân bằng danh mục và quản lý lợi nhuận vượt trội.'), ('Chuyên gia tư vấn tài chính doanh nghiệp (Corporate Finance Associate)', 'Tư vấn phát hành trái phiếu, cổ phiếu và tái cấu trúc nguồn vốn doanh nghiệp.')]}}, 'Marketing': {'discipline': 'tiếp thị số, nghiên cứu thị trường, sáng tạo nội dung, chạy chiến dịch quảng cáo đa kênh và quản trị thương hiệu chiến lược', 'intro': 'Marketing là nghệ thuật và khoa học thấu cảm nhu cầu con người, chuyển hóa sự thấu cảm đó thành những sản phẩm và thông điệp truyền thông có sức lan tỏa mạnh mẽ, tạo dựng giá trị bền vững cho thương hiệu và doanh thu cho doanh nghiệp. Một người làm tiếp thị hiện đại cần tư duy hai bán cầu não: vừa nhạy bén sáng tạo vừa kỷ luật với số liệu đo lường hiệu quả.', 'beginner': 'Lời khuyên cho người mới bắt đầu là hãy luôn lấy khách hàng làm trung tâm, rèn thói quen quan sát hành vi thực tế ngoài đời sống và không phỏng đoán cảm tính khi chưa kiểm chứng qua dữ liệu.', 'tools': ['Meta Ads Manager', 'Google Ads', 'Google Analytics 4', 'Canva / Adobe Photoshop', 'Ahrefs / SEMrush', 'CapCut / Premiere'], 'standards': ['Mô hình 4P / 7P Marketing Mix', 'Mô hình định vị STP', 'Khung hành trình khách hàng AIDA', 'Bộ quy tắc ứng xử quảng cáo quốc tế ICC'], 'roles': {1: [('Cộng tác viên sáng tạo nội dung (Content Creator Intern)', 'Viết bài truyền thông mạng xã hội, lên ý tưởng kịch bản video ngắn và hỗ trợ chụp ảnh sự kiện.'), ('Thực tập sinh nghiên cứu thị trường', 'Thực hiện phỏng vấn người tiêu dùng, thu thập ý kiến khảo sát và lập báo cáo tổng hợp phản hồi.'), ('Trợ lý tiếp thị sự kiện (Event Marketing Assistant)', 'Chuẩn bị hậu cần, vật phẩm quảng cáo và hỗ trợ điều phối gian hàng tại các sự kiện thương hiệu.')], 2: [('Chuyên viên tiếp thị số tập sự (Junior Digital Marketer)', 'Cài đặt và theo dõi chiến dịch quảng cáo trả phí trên Meta Ads và TikTok Ads với ngân sách nhỏ.'), ('Chuyên viên tối ưu hóa công cụ tìm kiếm (SEO Executive)', 'Nghiên cứu từ khóa, tối ưu bài viết chuẩn SEO On-page và xây dựng liên kết ngoài.'), ('Chuyên viên quản trị cộng đồng (Community Manager)', 'Quản lý tương tác trên Fanpage, giải đáp thắc mắc khách hàng và duy trì sự gắn kết của nhóm.')], 3: [('Chuyên viên hoạch định chiến dịch tiếp thị (Campaign Executive)', 'Lập kế hoạch truyền thông tích hợp (IMC Plan), phân bổ ngân sách và theo dõi chỉ số ROI/ROAS.'), ('Chuyên viên tối ưu hóa quảng cáo chuyển đổi (Performance Marketer)', 'Tối ưu hóa phễu quảng cáo, thực hiện A/B testing trang đích và giảm chi phí chuyển đổi (CPA).'), ('Chuyên viên quản trị thương hiệu tập sự (Assistant Brand Manager)', 'Giám sát tính nhất quán của bộ nhận diện thương hiệu và đánh giá mức độ nhận biết thương hiệu.')], 4: [('Chuyên viên tiếp thị chiến lược (Senior Marketing Executive)', 'Chịu trách nhiệm toàn diện về kế hoạch tăng trưởng doanh số và hình ảnh thương hiệu trong năm.'), ('Quản lý nhãn hàng tập sự (Junior Brand Manager)', 'Quản lý danh mục sản phẩm, định vị giá và triển khai các chiến dịch tung sản phẩm mới.'), ('Chuyên viên tư vấn truyền thông & Tiếp thị', 'Xây dựng chiến lược tiếp thị toàn diện cho các doanh nghiệp khách hàng và đối tác.')]}}, 'Logistics và Quản lý chuỗi cung ứng': {'discipline': 'vận tải đa phương thức, tập quán thương mại Incoterms 2020, quản lý kho bãi WMS, tối ưu hóa tồn kho và hoạch định chuỗi cung ứng toàn cầu', 'intro': 'Logistics và Quản lý chuỗi cung ứng là động cơ vận hành của thương mại toàn cầu, đảm bảo đúng sản phẩm đến đúng nơi, đúng lúc, với chi phí tối ưu nhất và tình trạng hoàn hảo. Khi chuỗi cung ứng thế giới ngày càng đối mặt với nhiều biến động địa chính trị, năng lực hoạch định mạng lưới, quản trị rủi ro vận tải và tối ưu hóa tồn kho trở thành năng lực cạnh tranh sống còn của doanh nghiệp.', 'beginner': 'Người mới bắt đầu cần làm chủ bản chất của 3 dòng chảy: Dòng hàng hóa vật lý, Dòng thông tin và Dòng tài chính; đồng thời ghi nhớ nằm lòng 11 điều kiện Incoterms 2020 trước khi nghiên cứu các mô hình vận tải phức tạp.', 'tools': ['Hệ thống quản lý kho WMS', 'Phần mềm ERP / SAP phân hệ MM/SD', 'Hệ thống khai hải quan điện tử VNACCS/VCIS', 'Microsoft Excel mô hình tồn kho EOQ'], 'standards': ['Tập quán thương mại quốc tế Incoterms 2020', 'Quy tắc vận đơn Hague-Visby', 'Tiêu chuẩn đóng gói hàng hóa quốc tế IATA/IMO', 'Mô hình SCOR'], 'roles': {1: [('Thực tập sinh kho vận cơ sở (Warehouse Operations Intern)', 'Hỗ trợ kiểm kê hàng hóa thực tế, dán mã vạch và phân loại hàng hóa vào giá kệ.'), ('Cộng tác viên theo dõi đơn hàng (Order Tracking Assistant)', 'Cập nhật trạng thái lộ trình vận chuyển trên hệ thống và thông báo thời gian giao nhận cho khách.'), ('Trợ lý chứng từ vận tải cơ bản', 'Sắp xếp hóa đơn thương mại, phiếu đóng gói hàng hóa và lưu trữ hồ sơ giao nhận.')], 2: [('Nhân viên chứng từ xuất nhập khẩu (Documentation Executive)', 'Soạn thảo và kiểm tra vận đơn đường biển (B/L), chứng nhận xuất xứ (C/O) và hóa đơn thương mại (Commercial Invoice).'), ('Điều phối viên vận tải nội địa (Fleet Coordinator)', 'Sắp xếp lịch trình xe tải, tối ưu hóa cung đường giao hàng và giám sát thời gian giao nhận.'), ('Chuyên viên quản lý kho bãi tập sự (Junior Warehouse Supervisor)', 'Theo dõi tồn kho tối thiểu, lập phiếu xuất nhập kho và hướng dẫn công nhân kho tuân thủ 5S.')], 3: [('Chuyên viên hiện trường cảng & Hải quan (Customs & Field Specialist)', 'Trực tiếp làm thủ tục thông quan hàng hóa tại cửa khẩu cảng biển/sân bay và giám sát mở tờ khai hải quan.'), ('Chuyên viên điều phối chuỗi cung ứng (Supply Chain Coordinator)', 'Theo dõi dòng chảy nguyên vật liệu, cân đối tiến độ giao hàng của nhà cung cấp và lịch sản xuất.'), ('Chuyên viên kinh doanh cước vận tải (Freight Forwarding Sales)', 'Tìm kiếm khách hàng có nhu cầu xuất nhập khẩu, tư vấn giá cước vận tải đường biển/hàng không.')], 4: [('Chuyên viên hoạch định chuỗi cung ứng (Supply Chain Planner)', 'Xây dựng kế hoạch dự báo nhu cầu (Demand Planning), tối ưu hóa lượng hàng tồn kho an toàn toàn mạng lưới.'), ('Quản lý vận tải & Khai thác logistics tập sự', 'Đàm phán hợp đồng dịch vụ logistics với các hãng tàu, đại lý vận tải và hãng hàng không quốc tế.'), ('Chuyên viên tư vấn giải pháp chuỗi cung ứng', 'Tái cấu trúc mạng lưới kho bãi phân phối và ứng dụng giải pháp số hóa chuỗi cung ứng bền vững.')]}}, 'Kinh doanh quốc tế': {'discipline': 'thương mại quốc tế, đàm phán hợp đồng ngoại thương, nghiên cứu thị trường toàn cầu, tài trợ thương mại và chiến lược thâm nhập thị trường', 'intro': 'Kinh doanh quốc tế mở ra chân trời hoạt động vượt ra ngoài ranh giới một quốc gia, kết nối các nền kinh tế thông qua thương mại hàng hóa, dịch vụ và đầu tư trực tiếp nước ngoài. Trong thời đại toàn cầu hóa, việc thấu hiểu sự khác biệt văn hóa kinh doanh, nắm vững luật lệ thương mại WTO, các hiệp định thương mại tự do (EVFTA, CPTPP) và sở hữu kỹ năng đàm phán ngoại thương sắc bén là chìa khóa mở cánh cửa sự nghiệp toàn cầu.', 'beginner': 'Lời khuyên cho người mới bắt đầu là rèn luyện khả năng tiếng Anh thương mại lưu loát, luôn cập nhật các biến động địa chính trị thế giới và tìm hiểu văn hóa kinh doanh của các đối tác thương mại lớn.', 'tools': ['Cơ sở dữ liệu thương mại quốc tế UN Comtrade', 'Hệ thống VNACCS/VCIS', 'Bộ chứng từ ngoại thương mẫu', 'Kênh đàm phán trực tuyến quốc tế'], 'standards': ['Công ước Vienna 1980 về mua bán hàng hóa quốc tế (CISG)', 'Incoterms 2020', 'Quy tắc thực hành thống nhất về tín dụng chứng từ UCP 600', 'Quy tắc xuất xứ trong các FTA'], 'roles': {1: [('Thực tập sinh thương mại quốc tế', 'Thu thập dữ liệu xuất nhập khẩu các thị trường mục tiêu và dịch thuật tài liệu giới thiệu sản phẩm sang tiếng Anh.'), ('Trợ lý nghiên cứu thị trường nước ngoài', 'Tìm kiếm danh bạ nhà nhập khẩu tiềm năng và hỗ trợ chuẩn bị tài liệu hội chợ thương mại quốc tế.'), ('Cộng tác viên hồ sơ xuất nhập khẩu', 'Rà soát tính đồng bộ giữa hợp đồng mua bán ngoại thương và các phụ lục đính kèm.')], 2: [('Chuyên viên phát triển thị trường xuất khẩu tập sự', 'Liên hệ với các khách hàng quốc tế qua email thương mại, gửi báo giá và mẫu hàng thử nghiệm.'), ('Nhân viên chứng từ ngoại thương (Export/Import Documentation)', 'Phát hành và kiểm tra bộ chứng từ thanh toán quốc tế: Hối phiếu, Hóa đơn thương mại, Vận đơn đường biển.'), ('Chuyên viên theo dõi tiến độ đơn hàng quốc tế', 'Phối hợp với nhà máy sản xuất để đảm bảo hàng hóa đáp ứng tiêu chuẩn kiểm định chất lượng xuất khẩu.')], 3: [('Chuyên viên đàm phán thương mại quốc tế', 'Trực tiếp tham gia thương thảo hợp đồng mua bán ngoại thương, điều khoản giá cả, phương thức thanh toán L/C và bảo hiểm hàng hóa.'), ('Chuyên viên phân tích thị trường toàn cầu', 'Đánh giá các rào cản kỹ thuật thương mại (TBT, SPS) và chính sách thuế quan tại các thị trường FTA.'), ('Chuyên viên tài trợ thương mại (Trade Finance Specialist)', 'Tư vấn mở và xử lý thư tín dụng chứng từ (L/C), bảo lãnh ngân hàng và bao thanh toán quốc tế.')], 4: [('Quản lý kinh doanh xuất nhập khẩu (Export/Import Manager Trainee)', 'Chịu trách nhiệm doanh số xuất khẩu khu vực, xây dựng mạng lưới đại lý phân phối độc quyền tại nước ngoài.'), ('Chuyên viên hoạch định chiến lược thâm nhập thị trường', 'Xây dựng phương án liên doanh, cấp phép nhượng quyền hoặc đầu tư trực tiếp vào thị trường mục tiêu.'), ('Chuyên gia tư vấn chính sách thương mại & Thuế quan', 'Hỗ trợ doanh nghiệp ứng phó với các vụ kiện phòng vệ thương mại (chống bán phá giá) trên thị trường quốc tế.')]}}, 'Luật kinh tế': {'discipline': 'pháp luật doanh nghiệp, pháp luật thương mại, soạn thảo và rà soát hợp đồng kinh tế, pháp luật cạnh tranh và giải quyết tranh chấp kinh doanh', 'intro': 'Luật kinh tế là tấm khiên pháp lý bảo vệ sự an toàn và tính bền vững cho mọi hoạt động sản xuất kinh doanh của doanh nghiệp. Trong môi trường kinh tế thị trường đầy biến động và cạnh tranh khốc liệt, việc am hiểu sâu sắc hành lang pháp lý, nhận diện sớm các rủi ro trong hợp đồng và tuân thủ các quy định quản trị nội bộ chính là yếu tố giúp doanh nghiệp phát triển bền vững và tránh các thiệt hại tài chính nặng nề.', 'beginner': 'Đối với người mới bắt đầu học luật, kỹ năng tra cứu văn bản quy phạm pháp luật, tư duy giải thích điều luật dựa trên tinh thần lập pháp và kỹ năng lập luận logic, sử dụng từ ngữ chính xác, không đa nghĩa là những năng lực sống còn.', 'tools': ['Cơ sở dữ liệu Thư Viện Pháp Luật / LuatVietnam', 'Cổng thông tin quốc gia về đăng ký doanh nghiệp', 'Mẫu hợp đồng kinh tế thương mại chuẩn', 'Phần mềm quản lý văn bản pháp lý'], 'standards': ['Luật Doanh nghiệp 2020', 'Luật Thương mại 2005', 'Bộ luật Dân sự 2015', 'Luật Cạnh tranh', 'Quy tắc tố tụng Trọng tài VIAC'], 'roles': {1: [('Thực tập sinh pháp lý cơ sở (Legal Intern)', 'Hỗ trợ tra cứu văn bản quy phạm pháp luật, cập nhật thông tư nghị định mới và tóm tắt bản án.'), ('Trợ lý hồ sơ doanh nghiệp', 'Chuẩn bị các biểu mẫu hồ sơ thành lập doanh nghiệp, thay đổi nội dung đăng ký kinh doanh.'), ('Cộng tác viên lưu trữ hồ sơ pháp lý', 'Quản lý và số hóa các hợp đồng kinh tế, biên bản họp hội đồng quản trị của công ty.')], 2: [('Chuyên viên tư vấn thủ tục doanh nghiệp (Corporate Paralegal)', 'Soạn thảo hồ sơ cấp giấy phép con, đăng ký thay đổi vốn điều lệ và thủ tục mở chi nhánh.'), ('Chuyên viên rà soát hợp đồng tập sự', 'Rà soát tính hợp pháp của các điều khoản hợp đồng mua bán hàng hóa, dịch vụ cơ bản.'), ('Trợ lý luật sư kinh tế', 'Thu thập tài liệu chứng cứ, soạn thảo đơn từ và hỗ trợ luật sư trong quá trình chuẩn bị phiên xét xử.')], 3: [('Chuyên viên pháp chế doanh nghiệp (Legal Officer)', 'Trực tiếp soạn thảo các hợp đồng thương mại phức tạp, xây dựng nội quy lao động và quy chế quản trị nội bộ.'), ('Chuyên viên tuân thủ pháp luật (Compliance Officer)', 'Giám sát việc tuân thủ các quy định về an toàn lao động, môi trường, bảo vệ dữ liệu cá nhân trong tổ chức.'), ('Thư ký hội đồng trọng tài thương mại', 'Hỗ trợ thủ tục tố tụng tại Trung tâm Trọng tài quốc tế Việt Nam (VIAC), ghi biên bản hòa giải.')], 4: [('Chuyên viên pháp chế cao cấp (Senior Legal Counsel)', 'Đàm phán các điều khoản pháp lý trong các thương vụ mua bán sáp nhập (M&A), hợp đồng đầu tư mạo hiểm.'), ('Luật sư tập sự chuyên ngành thương mại (Associate Lawyer)', 'Đại diện theo ủy quyền tham gia giải quyết tranh chấp hợp đồng tại Tòa án và Trọng tài thương mại.'), ('Chuyên gia tư vấn tái cấu trúc doanh nghiệp & Phá sản', 'Tư vấn phương án giải thể, sáp nhập, phân chia doanh nghiệp và xử lý nợ xấu theo quy định pháp luật.')]}}, 'Quản trị kinh doanh': {'discipline': 'hoạch định chiến lược kinh doanh, quản lý dự án, phân tích nghiệp vụ, tối ưu hóa vận hành doanh nghiệp và phát triển năng lực lãnh đạo', 'intro': 'Quản trị kinh doanh là nghệ thuật và khoa học điều phối mọi nguồn lực (nhân lực, tài chính, công nghệ, thời gian) để hiện thực hóa các mục tiêu chiến lược của tổ chức trong môi trường cạnh tranh. Một nhà quản trị giỏi cần sở hữu tầm nhìn bao quát chuỗi giá trị doanh nghiệp, khả năng phân tích số liệu nhạy bén và năng lực lãnh đạo, truyền cảm hứng cho đội ngũ.', 'beginner': 'Người mới bắt đầu học quản trị không nên chỉ học lý thuyết quản trị trừu tượng mà cần bắt đầu từ việc làm chủ công cụ phân tích số liệu trên Excel, hiểu cách đọc báo cáo tài chính và quan sát cách thức vận hành thực tế của các doanh nghiệp xung quanh.', 'tools': ['Microsoft Excel quản trị kinh doanh', 'Phần mềm quản lý dự án Trello / Jira / Asana', 'Power BI báo cáo quản trị', 'Mô hình phân tích SWOT / PESTEL / Porter 5 Forces'], 'standards': ['Chuẩn quản lý chất lượng ISO 9001', 'Phương pháp quản lý mục tiêu OKR / KPI', 'Khung quản lý dự án PMBOK của PMI', 'Mô hình quản trị tinh gọn Lean Management'], 'roles': {1: [('Thực tập sinh quản trị cơ sở (Business Intern)', 'Hỗ trợ thu thập tài liệu thị trường, tổng hợp số liệu khảo sát và lập biên bản cuộc họp.'), ('Trợ lý hành chính văn phòng', 'Soạn thảo văn bản hành chính, quản lý lịch làm việc và điều phối công tác hậu cần cuộc họp.'), ('Cộng tác viên nghiên cứu đối thủ cạnh tranh', 'Thu thập thông tin giá bán, chương trình khuyến mãi của các đối thủ trên thị trường.')], 2: [('Chuyên viên phân tích nghiệp vụ kinh doanh (Business Analyst Trainee)', 'Khảo sát quy trình làm việc hiện tại, xác định điểm nghẽn và đề xuất cải tiến thủ tục.'), ('Trợ lý quản lý dự án (Project Assistant)', 'Theo dõi tiến độ thực hiện các mốc công việc trên Jira/Trello và lập báo cáo trạng thái dự án.'), ('Chuyên viên phát triển kinh doanh tập sự (Junior BD)', 'Tìm kiếm danh bạ khách hàng tiềm năng, liên hệ chào hàng và giới thiệu dịch vụ doanh nghiệp.')], 3: [('Chuyên viên quản lý dự án (Project Coordinator)', 'Trực tiếp điều phối phân bổ nguồn lực dự án, quản lý rủi ro và kiểm soát ngân sách thực hiện.'), ('Chuyên viên tối ưu hóa quy trình (Process Optimization Specialist)', 'Áp dụng phương pháp Lean/Kaizen để rút ngắn thời gian chu kỳ sản xuất hoặc cung ứng dịch vụ.'), ('Chuyên viên hoạch định chiến lược kinh doanh', 'Phân tích số liệu thị trường, xây dựng mô hình dự báo doanh thu và đề xuất chiến lược giá.')], 4: [('Quản trị viên tập sự (Management Trainee - MT)', 'Tham gia chương trình đào tạo lãnh đạo tương lai luân chuyển qua các phòng ban cốt lõi.'), ('Chuyên viên tư vấn quản trị chiến lược (Strategy Associate)', 'Xây dựng đề án tái cấu trúc doanh nghiệp, kế hoạch mở rộng thị trường và chiến lược M&A.'), ('Trợ lý Giám đốc điều hành (Executive Assistant to CEO)', 'Phối hợp với ban giám đốc giám sát việc thực thi các mục tiêu OKR/KPI trên toàn công ty.')]}}, 'Công nghệ tài chính': {'discipline': 'hệ thống thanh toán số, ví điện tử, ngân hàng số mở (Open Banking), mô hình hóa định lượng tài chính bằng Python và công nghệ chuỗi khối', 'intro': 'Công nghệ tài chính (Fintech) là cuộc cách mạng tái định hình toàn bộ phương thức con người thanh toán, tiết kiệm, vay vốn và đầu tư thông qua sức mạnh của công nghệ số. Sự giao thoa giữa kỹ thuật phần mềm hiện đại và nghiệp vụ tài chính khắt khe đòi hỏi các kỹ sư Fintech vừa phải am hiểu sâu sắc về bảo mật giao dịch, kiến trúc microservices vừa phải vững vàng về quy định pháp lý tài chính.', 'beginner': 'Người mới bắt đầu cần làm chủ kỹ thuật lập trình Python ứng dụng trong xử lý dữ liệu chuỗi thời gian, hiểu cơ chế vận hành của cổng thanh toán điện tử và nắm vững các quy định an toàn bảo mật thanh toán số.', 'tools': ['Python (Pandas, NumPy, Scikit-learn)', 'Hệ quản trị cơ sở dữ liệu PostgreSQL', 'Cổng thanh toán API giả lập (Stripe / VNPay sandbox)', 'Docker'], 'standards': ['Chuẩn an ninh dữ liệu thẻ thanh toán PCI-DSS', 'Chuẩn kết nối ngân hàng mở Open Banking API', 'Khung pháp lý thử nghiệm Sandbox Fintech của NHNN', 'Quy tắc xác thực khách hàng điện tử eKYC'], 'roles': {1: [('Thực tập sinh phân tích dữ liệu giao dịch', 'Thu thập số liệu giao dịch tài chính, kiểm tra tính toàn vẹn và lập báo cáo thống kê bằng Python/Excel.'), ('Cộng tác viên hỗ trợ kỹ thuật thanh toán số', 'Theo dõi trạng thái các giao dịch trực tuyến và hỗ trợ tái hiện các trường hợp giao dịch thất bại.'), ('Trợ lý nghiên cứu giải pháp Fintech', 'Tìm hiểu các xu hướng ví điện tử, Buy Now Pay Later (BNPL) và ngân hàng số thế giới.')], 2: [('Lập trình viên tích hợp cổng thanh toán (Payment Integration Developer)', 'Tích hợp API cổng thanh toán, xử lý phản hồi Webhook và mã hóa bảo mật chữ ký số giao dịch.'), ('Chuyên viên phân tích hệ thống ví điện tử tập sự', 'Mô hình hóa luồng nạp - chuyển - rút tiền và thiết lập quy trình đối soát giao dịch tự động.'), ('Chuyên viên phân tích dữ liệu người dùng tài chính', 'Phân tích hành vi chi tiêu qua ví điện tử và xây dựng các phân khúc khách hàng tiềm năng.')], 3: [('Kỹ sư phát triển sản phẩm Fintech (Fintech Product Engineer)', 'Xây dựng các module tính toán lãi suất tự động, chấm điểm tín dụng vi mô (Micro-scoring).'), ('Chuyên viên quản trị rủi ro gian lận giao dịch (Fraud Risk Analyst)', 'Xây dựng các quy tắc phát hiện giao dịch bất thường (Fraud Detection Rules) thời gian thực.'), ('Chuyên viên tuân thủ pháp chế Fintech (Fintech Compliance Specialist)', 'Đánh giá tính tuân thủ quy định phòng chống rửa tiền (AML/CFT) và bảo vệ dữ liệu tài chính.')], 4: [('Kỹ sư tài chính định lượng (Quantitative Finance Developer)', 'Hiện thực hóa các thuật toán giao dịch tự động, mô hình hóa rủi ro tín dụng bằng Machine Learning.'), ('Quản lý sản phẩm ngân hàng số (Digital Banking Product Manager)', 'Chịu trách nhiệm thiết kế và nâng cấp các tính năng trải nghiệm số trên ứng dụng Mobile Banking.'), ('Chuyên gia tư vấn chuyển đổi số ngành ngân hàng', 'Tư vấn kiến trúc Open API và lộ trình hiện đại hóa hệ thống Core Banking cho các ngân hàng thương mại.')]}}, 'Thiết kế đồ họa': {'discipline': 'nghệ thuật thị giác, thiết kế nhận diện thương hiệu, đồ họa vector, nghệ thuật chữ (Typography), thiết kế giao diện UI/UX và truyền thông thị giác', 'intro': 'Thiết kế đồ họa là nghệ thuật kết hợp hình ảnh, màu sắc và kiểu chữ để truyền tải thông điệp một cách ấn tượng, dẫn dắt cảm xúc và định hình nhận thức của công chúng về một thương hiệu. Một nhà thiết kế xuất sắc không chỉ tạo ra các tác phẩm bắt mắt mà là người giải quyết bài toán giao tiếp thị giác, giúp sản phẩm trở nên thân thiện và tạo được sự kết nối sâu sắc với người dùng.', 'beginner': 'Người mới bắt đầu cần rèn luyện nền tảng mỹ thuật cơ bản: quy luật thị giác, lý thuyết màu sắc và hệ thống lưới (Grid System) trước khi phụ thuộc hoàn toàn vào các phần mềm đồ họa.', 'tools': ['Adobe Photoshop', 'Adobe Illustrator', 'Figma', 'Adobe InDesign', 'Bảng vẽ điện tử Wacom'], 'standards': ['Nguyên lý thị giác Gestalt', 'Hệ thống phân cấp thị giác (Visual Hierarchy)', 'Quy chuẩn thiết kế nhận diện thương hiệu (Brand Guidelines)', 'Tiêu chuẩn đồ họa in ấn CMYK / Web RGB'], 'roles': {1: [('Cộng tác viên thiết kế đồ họa cơ sở', 'Hỗ trợ chỉnh sửa kích thước ảnh, cắt ghép hình ảnh sản phẩm và thiết kế banner mạng xã hội đơn giản.'), ('Thực tập sinh đồ họa truyền thông', 'Thiết kế poster thông báo nội bộ, slide thuyết trình thương hiệu và đồ họa bảng tin.'), ('Trợ lý xử lý hình ảnh số (Photo Retoucher)', 'Tách nền ảnh, chỉnh sửa màu sắc cơ bản và sắp xếp kho tài nguyên đồ họa của công ty.')], 2: [('Chuyên viên thiết kế đồ họa 2D (Graphic Designer)', 'Thiết kế ấn phẩm truyền thông đa kênh: infographic, bao bì sản phẩm, catalog và brochure giới thiệu dịch vụ.'), ('Họa sĩ minh họa vector (Vector Illustrator)', 'Vẽ nhân vật minh họa, biểu tượng icon và hình họa vector cho các chiến dịch quảng cáo.'), ('Chuyên viên thiết kế giao diện UI tập sự', 'Thiết kế màn hình ứng dụng di động trên Figma tuân thủ Design System có sẵn.')], 3: [('Chuyên viên thiết kế nhận diện thương hiệu (Brand Identity Designer)', 'Sáng tạo logo, lựa chọn bảng màu, kiểu chữ và biên soạn cẩm nang quy chuẩn thương hiệu (Brand Guideline).'), ('Chuyên viên thiết kế trải nghiệm người dùng (UI/UX Designer)', 'Nghiên cứu luồng người dùng (User Flow), tạo wireframe và thiết kế nguyên mẫu tương tác (Interactive Prototype).'), ('Chuyên viên thiết kế bao bì & Ấn phẩm cao cấp', 'Thiết kế kết cấu bao bì sản phẩm thực tế, lựa chọn chất liệu giấy và kỹ thuật gia công in ấn (ép kim, dập nổi).')], 4: [('Giám đốc nghệ thuật tập sự (Junior Art Director)', 'Định hướng phong cách hình ảnh cho toàn bộ chiến dịch quảng cáo lớn, chỉ đạo đội ngũ thiết kế và nhiếp ảnh.'), ('Trưởng nhóm thiết kế sáng tạo (Lead Creative Designer)', 'Chịu trách nhiệm về chất lượng thẩm mỹ và tính nhất quán thương hiệu của mọi sản phẩm đầu ra.'), ('Chuyên gia tư vấn chiến lược nhận diện thương hiệu', 'Tư vấn tái định vị hình ảnh thương hiệu (Rebranding) cho các doanh nghiệp và tập đoàn kinh tế.')]}}, 'Truyền thông đa phương tiện': {'discipline': 'sản xuất video số, kỹ xảo điện ảnh, thiết kế tương tác số, biên tập âm thanh và sản xuất nội dung truyền thông đa nền tảng', 'intro': 'Truyền thông đa phương tiện là sự kết hợp bùng nổ giữa công nghệ thông tin và nghệ thuật nghe nhìn để sáng tạo ra các sản phẩm nội dung tương tác sống động phục vụ giải trí, giáo dục và quảng cáo số. Khi video ngắn và các định dạng nghe nhìn trực quan trở thành ngôn ngữ thống trị trên Internet, chuyên viên truyền thông đa phương tiện chính là những đạo diễn số kiến tạo xu hướng và thu hút hàng triệu lượt xem.', 'beginner': 'Người mới bắt đầu nên bắt đầu từ việc nắm vững ngôn ngữ điện ảnh cơ bản: các cỡ cảnh quay, góc máy, quy tắc 1/3 và nhịp điệu cắt dựng trước khi học các kỹ xảo phức tạp.', 'tools': ['Adobe Premiere Pro', 'Adobe After Effects', 'Adobe Audition', 'Figma', 'Máy quay phim kỹ thuật số & Đèn chiếu sáng'], 'standards': ['Quy chuẩn khung hình và tốc độ 24fps/30fps/60fps', 'Tiêu chuẩn âm thanh phát sóng LUFS', 'Nguyên tắc dàn cảnh điện ảnh (Mise-en-scène)', 'Bản quyền âm nhạc và hình ảnh số'], 'roles': {1: [('Kỹ thuật viên dựng video cơ sở (Video Editor Intern)', 'Cắt ghép video thô, đồng bộ âm thanh và chèn phụ đề cho các video ngắn trên TikTok/Reels.'), ('Trợ lý quay phim & Ánh sáng', 'Hỗ trợ sắp xếp đèn chiếu sáng, quản lý thiết bị máy quay và thu âm hiện trường tại trường quay.'), ('Cộng tác viên sản xuất nội dung số', 'Tìm kiếm tài nguyên âm nhạc, hiệu ứng âm thanh và hỗ trợ lên kịch bản phân cảnh (Storyboard).')], 2: [('Chuyên viên biên tập video chuyên nghiệp (Video Editor)', 'Dựng hoàn chỉnh các video phóng sự, video giới thiệu doanh nghiệp và quảng cáo TVC ngắn.'), ('Chuyên viên kỹ xảo hình ảnh tập sự (Junior Motion Graphic Designer)', 'Thiết kế đồ họa chuyển động 2D, hiệu ứng chữ chuyển động (Typography Motion) và intro/outro.'), ('Kỹ thuật viên âm thanh truyền thông (Sound Designer)', 'Xử lý tạp âm, cân bằng âm lượng và lồng ghép hiệu ứng âm thanh (Foley) cho video.')], 3: [('Đạo diễn hình ảnh / Quay phim chính (Cinematographer)', 'Chịu trách nhiệm về góc máy, ánh sáng và phong cách thị giác của toàn bộ sản phẩm video.'), ('Chuyên viên thiết kế đồ họa chuyển động cao cấp (Motion Artist)', 'Tạo các kỹ xảo hình ảnh 3D phức tạp, kết hợp kỹ thuật bóc tách phông xanh và gắn tracking đối tượng.'), ('Chuyên viên sản xuất nội dung đa nền tảng (Multimedia Producer)', 'Quản lý toàn bộ quy trình tiền kỳ, sản xuất và hậu kỳ cho các series video truyền thông lớn.')], 4: [('Giám đốc sản xuất nội dung số (Digital Production Manager)', 'Lập kế hoạch sản xuất, quản lý ngân sách làm phim và điều phối toàn bộ đoàn quay phim chuyên nghiệp.'), ('Chuyên viên tư vấn chiến lược nội dung nghe nhìn', 'Xây dựng định dạng nội dung số độc quyền và chiến lược phát hành video đa kênh cho các tập đoàn truyền thông.'), ('Nhà sáng tạo nội dung đa phương tiện độc lập', 'Xây dựng kênh truyền thông cá nhân có tầm ảnh hưởng lớn và hợp tác thương mại với các nhãn hàng uy tín.')]}}, 'Ngôn ngữ Anh': {'discipline': 'ngôn ngữ học ứng dụng, biên phiên dịch chuyên ngành, viết học thuật, giao tiếp liên văn hóa và biên tập nội dung tiếng Anh chuyên nghiệp', 'intro': 'Ngôn ngữ Anh không chỉ đơn thuần là công cụ giao tiếp toàn cầu mà là chìa khóa tiếp cận kho tàng tri thức nhân loại và mở ra cơ hội làm việc trong môi trường đa quốc gia. Cử nhân Ngôn ngữ Anh hiện đại không chỉ thành thạo 4 kỹ năng Nghe - Nói - Đọc - Viết mà còn sở hữu tư duy phân tích ngôn ngữ học sắc sảo, năng lực biên dịch các văn bản học thuật / thương mại phức tạp và kỹ năng đàm phán xuyên văn hóa.', 'beginner': 'Người mới bắt đầu cần chuẩn hóa hệ thống phát âm theo Bảng ký hiệu ngữ âm quốc tế (IPA), nắm chắc ngữ pháp cấu trúc câu học thuật và rèn thói quen đọc tài liệu tiếng Anh mỗi ngày.', 'tools': ['Phần mềm hỗ trợ dịch thuật CAT Tools (Trados, MemoQ)', 'Grammarly / Hemingway Editor', 'Từ điển chuẩn Oxford / Cambridge Advanced', 'Corpus of Contemporary American English (COCA)'], 'standards': ['Khung tham chiếu trình độ ngôn ngữ chung châu Âu (CEFR C1/C2)', 'Quy chuẩn trích dẫn học thuật APA / MLA', 'Quy tắc dịch thuật văn bản chuyên ngành', 'Bộ quy tắc đạo đức nghề biên phiên dịch'], 'roles': {1: [('Cộng tác viên biên dịch tài liệu cơ bản', 'Dịch thuật các bài viết tin tức, thư từ thương mại và tài liệu hướng dẫn sử dụng đơn giản.'), ('Trợ lý giảng dạy tiếng Anh (Teaching Assistant - TA)', 'Hỗ trợ giáo viên nước ngoài quản lý lớp học, kiểm tra bài tập về nhà và luyện phát âm cho học viên.'), ('Cộng tác viên biên tập nội dung tiếng Anh', 'Kiểm tra lỗi chính tả, ngữ pháp và định dạng các văn bản truyền thông bằng tiếng Anh.')], 2: [('Chuyên viên biên dịch chuyên ngành (Technical Translator)', 'Dịch thuật các tài liệu hợp đồng kinh tế, tài liệu kỹ thuật công nghệ thông tin hoặc y tế.'), ('Chuyên viên sáng tạo nội dung tiếng Anh (English Content Writer)', 'Viết bài chuẩn SEO tiếng Anh cho website quốc tế, soạn thảo thông cáo báo chí và bản tin nội bộ.'), ('Điều phối viên đối ngoại quốc tế tập sự', 'Phụ trách tiếp đón đoàn khách nước ngoài, soạn thảo thư tín ngoại giao và phiên dịch các cuộc họp đơn giản.')], 3: [('Phiên dịch viên hội thảo nối tiếp (Consecutive Interpreter)', 'Phiên dịch trực tiếp tại các cuộc đàm phán thương mại, hội nghị khách hàng và chuyến công tác thực địa.'), ('Chuyên viên phát triển chương trình đào tạo ngôn ngữ', 'Thiết kế giáo trình tiếng Anh chuyên ngành (ESP) cho doanh nghiệp và xây dựng bài kiểm tra đánh giá năng lực.'), ('Biên tập viên xuất bản tiếng Anh', 'Hiệu đính và biên tập các bản thảo sách dịch, bài báo khoa học chuẩn bị xuất bản quốc tế.')], 4: [('Phiên dịch viên hội nghị cabin (Simultaneous Conference Interpreter)', 'Phiên dịch song song tại các hội nghị thượng đỉnh quốc tế, diễn đàn kinh tế ngoại giao cấp cao.'), ('Quản lý dự án dịch thuật & Bản địa hóa (Localization Project Manager)', 'Điều phối các dự án bản địa hóa phần mềm, game và website cho các tập đoàn toàn cầu.'), ('Chuyên gia tư vấn giao tiếp liên văn hóa & Đối ngoại', 'Tư vấn chiến lược truyền thông quốc tế và đào tạo kỹ năng đàm phán đa văn hóa cho các nhà lãnh đạo.')]}}, 'Quan hệ quốc tế': {'discipline': 'chính trị thế giới, địa chính trị, luật pháp quốc tế, ngoại giao công chúng, phân tích chính sách đối ngoại và đàm phán đa phương', 'intro': 'Quan hệ quốc tế là ngành khoa học nghiên cứu sự tương tác giữa các quốc gia, các tổ chức quốc tế và các chủ thể phi nhà nước trong không gian toàn cầu. Trong một thế giới đa cực đầy biến động với các thách thức an ninh truyền thống và phi truyền thống, năng lực phân tích địa chính trị, dự báo cục diện khu vực và kỹ năng ngoại giao đa phương là những phẩm chất cao quý của những người làm công tác đối ngoại.', 'beginner': 'Sinh viên năm nhất cần xây dựng thói quen đọc các tạp chí phân tích chính sách uy tín thế giới (Foreign Affairs, The Diplomat, Foreign Policy) và rèn luyện tư duy phản biện khi tiếp cận các nguồn tin đa chiều.', 'tools': ['Cơ sở dữ liệu Liên Hợp Quốc UN Data', 'Phần mềm quản lý tài liệu Zotero / Mendeley', 'Bản đồ địa chính trị số GIS', 'Cổng thông tin Bộ Ngoại giao'], 'standards': ['Hiến chương Liên Hợp Quốc', 'Công ước Vienna 1961 về quan hệ ngoại giao', 'Quy chuẩn lễ tân ngoại giao quốc tế', 'Phương pháp luận phân tích chính sách công'], 'roles': {1: [('Thực tập sinh nghiên cứu quốc tế cơ sở', 'Tổng hợp tin tức thời sự đối ngoại hàng ngày, chuẩn bị tài liệu điểm báo và dịch thuật báo cáo ngắn.'), ('Tình nguyện viên hỗ trợ sự kiện ngoại giao', 'Hỗ trợ công tác lễ tân đón tiếp đoàn đại biểu quốc tế tại các hội nghị thanh niên toàn cầu.'), ('Trợ lý dự án phi chính phủ (NGO Intern)', 'Tham gia hỗ trợ hậu cần các chương trình phát triển cộng đồng và giao lưu văn hóa quốc tế.')], 2: [('Chuyên viên đối ngoại doanh nghiệp tập sự (Corporate Affairs Trainee)', 'Duy trì quan hệ với các hiệp hội doanh nghiệp nước ngoài (AmCham, EuroCham) và tổ chức sự kiện kết nối.'), ('Trợ lý phân tích chính sách đối ngoại', 'Soạn thảo các bản tóm tắt phân tích về biến động chính sách kinh tế của các đối tác thương mại lớn.'), ('Điều phối viên chương trình giao lưu văn hóa quốc tế', 'Xây dựng kế hoạch tổ chức các tuần lễ văn hóa, triển lãm giáo dục và trao đổi sinh viên quốc tế.')], 3: [('Chuyên viên quan hệ công chúng quốc tế (Global PR Specialist)', 'Xây dựng hình ảnh thương hiệu quốc gia, quản lý các chiến dịch ngoại giao công chúng và thông cáo báo chí nước ngoài.'), ('Chuyên viên điều phối dự án viện trợ quốc tế', 'Quản lý tiến độ giải ngân, giám sát đánh giá hiệu quả (M&E) các dự án phát triển bền vững của UNDP/WB.'), ('Cán bộ lễ tân ngoại giao & Hợp tác quốc tế', 'Trực tiếp sắp xếp nghi lễ ngoại giao, bố trí khánh tiết và hỗ trợ đàm phán các thỏa thuận ghi nhớ (MOU).')], 4: [('Chuyên viên phân tích rủi ro chính trị (Political Risk Analyst)', 'Đánh giá các rủi ro địa chính trị, chính sách đầu tư cho các quỹ đầu tư mạo hiểm và tập đoàn đa quốc gia.'), ('Cán bộ đối ngoại chính thức / Tùy viên ngoại giao tập sự', 'Công tác tại các cơ quan ngoại giao nhà nước, sở ngoại vụ hoặc cơ quan đại diện Việt Nam ở nước ngoài.'), ('Chuyên gia tư vấn chính sách công quốc tế', 'Tư vấn cho các tổ chức quốc tế về các vấn đề biến đổi khí hậu, an ninh năng lượng và thương mại tự do.')]}}, 'Tâm lý học': {'discipline': 'tâm lý học đại cương, đánh giá tâm lý chuẩn hóa, tham vấn tâm lý cơ bản, tâm lý học hành vi tổ chức và can thiệp tâm lý ứng dụng', 'intro': 'Tâm lý học là ngành khoa học nghiên cứu về tâm trí, cảm xúc và hành vi của con người. Trong xã hội hiện đại với nhịp sống hối hả và áp lực tinh thần gia tăng, vai trò của các chuyên gia tâm lý trở nên cấp thiết hơn bao giờ hết: từ việc nâng đỡ sức khỏe tinh thần cho cộng đồng, hỗ trợ tâm lý học đường đến việc tối ưu hóa động lực làm việc và trải nghiệm nhân viên trong các tổ chức doanh nghiệp.', 'beginner': 'Điều quan trọng nhất đối với người mới học tâm lý là rèn luyện thái độ lắng nghe không phán xét, thấu cảm sâu sắc và tuân thủ nghiêm ngặt các nguyên tắc đạo đức nghề nghiệp về bảo mật thông tin thân chủ.', 'tools': ['Phần mềm phân tích thống kê SPSS / Jamovi', 'Bộ công cụ trắc nghiệm tâm lý chuẩn hóa (DASS-21, MBTI, BDI, WISC)', 'Sổ tay ghi chép lâm sàng', 'Phần mềm khảo sát Qualtrics / Google Forms'], 'standards': ['Bộ quy tắc đạo đức nghề nghiệp của Hiệp hội Tâm lý học Hoa Kỳ (APA)', 'Cẩm nang chẩn đoán DSM-5', 'Tiêu chuẩn đạo đức nghiên cứu trên người', 'Quy trình tham vấn tâm lý bảo mật'], 'roles': {1: [('Thực tập sinh nghiên cứu tâm lý cơ sở', 'Hỗ trợ thu thập dữ liệu bảng hỏi khảo sát tâm lý, nhập liệu số liệu vào SPSS và hỗ trợ phòng lab.'), ('Tình nguyện viên đường dây trợ giúp tâm lý', 'Tiếp nhận cuộc gọi ban đầu, lắng nghe chia sẻ của người gọi và chuyển tiếp cho chuyên gia trực tiếp.'), ('Cộng tác viên tổ chức hoạt động cộng đồng', 'Hỗ trợ điều phối các buổi tọa đàm về sức khỏe tinh thần và giáo dục kỹ năng sống cho học sinh.')], 2: [('Trợ lý đánh giá tâm lý (Psychological Assessment Assistant)', 'Hướng dẫn thân chủ làm các bài trắc nghiệm tâm lý chuẩn hóa, chấm điểm và lập hồ sơ dữ liệu thô.'), ('Chuyên viên tâm trị liệu học đường tập sự', 'Quan sát hành vi học sinh, hỗ trợ giáo viên chủ nhiệm nhận diện các dấu hiệu căng thẳng tâm lý học đường.'), ('Chuyên viên nghiên cứu hành vi người tiêu dùng', 'Ứng dụng các nguyên lý tâm lý học để phỏng vấn sâu người tiêu dùng và phân tích động cơ mua hàng.')], 3: [('Chuyên viên tham vấn tâm lý cơ sở (Counselor Trainee)', 'Thực hiện các phiên tham vấn tâm lý cá nhân dưới sự giám sát chuyên môn (Supervision) của chuyên gia chính.'), ('Chuyên viên phát triển nhân sự & Văn hóa doanh nghiệp (HR/OD)', 'Thiết kế các chương trình chăm sóc sức khỏe tinh thần nhân viên (EAP), đánh giá mức độ gắn kết đội ngũ.'), ('Chuyên viên can thiệp tâm lý giáo dục đặc biệt', 'Xây dựng kế hoạch can thiệp hành vi cá nhân hóa cho trẻ em có nhu cầu đặc biệt (tự kỷ, tăng động).')], 4: [('Chuyên viên tham vấn tâm lý chính thức', 'Chịu trách nhiệm độc lập các ca tham vấn tâm lý cho thân chủ về căng thẳng, lo âu, mối quan hệ và định hướng cuộc sống.'), ('Chuyên gia tâm lý học tổ chức & Nhân sự (I/O Psychologist)', 'Tư vấn cho ban giám đốc về văn hóa lãnh đạo, cơ chế động viên nhân sự và quản trị sự thay đổi tâm lý tổ chức.'), ('Nghiên cứu viên tâm lý học ứng dụng', 'Chủ trì các đề tài nghiên cứu về sức khỏe tâm thần cộng đồng và công bố các phát hiện học thuật trên tạp chí chuyên ngành.')]}}, 'Kỹ thuật điện': {'discipline': 'lý thuyết mạch điện, an toàn điện công nghiệp, thiết kế hệ thống cung cấp điện, máy điện - khí cụ điện và lập trình PLC', 'intro': 'Kỹ thuật điện là xương sống cung cấp và chuyển hóa năng lượng cho toàn bộ nền văn minh công nghiệp hiện đại. Từ hệ thống lưới điện quốc gia siêu cao áp, các trạm biến áp phân phối đến hệ thống điện động lực trong các nhà máy sản xuất thông minh và các nguồn năng lượng tái tạo (điện gió, điện mặt trời), kỹ sư điện là những người giữ cho dòng năng lượng huyết mạch của đất nước luôn ổn định và an toàn.', 'beginner': 'Nguyên tắc số một của ngành kỹ thuật điện là an toàn: phải luôn tuân thủ nghiêm ngặt quy trình ngắt nguồn, kiểm tra bút thử điện và nối đất an toàn trước khi thao tác trên bất kỳ thiết bị nào.', 'tools': ['AutoCAD Electrical', 'MATLAB / Simulink SimPowerSystems', 'Phần mềm mô phỏng mạch Multisim', 'Bộ lập trình PLC Siemens / Mitsubishi'], 'standards': ['Quy chuẩn kỹ thuật quốc gia về kỹ thuật điện QCVN', 'Tiêu chuẩn thiết kế điện TCVN', 'Tiêu chuẩn quốc tế IEC 60364', 'Quy trình an toàn điện EVN'], 'roles': {1: [('Kỹ thuật viên điện cơ sở', 'Hỗ trợ lắp đặt đường dây điện chiếu sáng, đo kiểm thông mạch và bảo dưỡng thiết bị đóng cắt đơn giản.'), ('Trợ lý đọc bản vẽ điện', 'Kiểm tra danh mục vật tư thiết bị điện theo bản vẽ sơ đồ nguyên lý và bóc tách số lượng.'), ('Thực tập sinh an toàn điện công nghiệp', 'Tham gia các khóa huấn luyện an toàn lao động điện và hỗ trợ kiểm tra trang thiết bị bảo hộ.')], 2: [('Chuyên viên thiết kế bản vẽ điện AutoCAD (Electrical CAD Drafter)', 'Vẽ sơ đồ nguyên lý tủ điện phân phối, sơ đồ đi dây chiếu sáng và mặt bằng cấp điện công trình.'), ('Kỹ sư giám sát thi công hệ thống điện tập sự', 'Giám sát công nhân lắp đặt máng cáp, kéo rải cáp động lực và đấu nối tủ điện tại công trường.'), ('Kỹ thuật viên thí nghiệm điện cơ sở', 'Đo điện trở cách điện bằng Megohmmeter, kiểm tra điện trở nối đất an toàn và ghi chép nhật ký đo đạc.')], 3: [('Kỹ sư lập trình điều khiển PLC & Tự động hóa trạm', 'Lập trình điều khiển logic cho hệ thống máy phát điện dự phòng, chuyển nguồn tự động ATS bằng PLC.'), ('Kỹ sư thiết kế hệ thống cơ điện công trình (M&E Electrical Engineer)', 'Tính toán phụ tải điện, chọn tiết diện dây dẫn, tính toán ngắn mạch và lựa chọn thiết bị bảo vệ CB.'), ('Kỹ sư vận hành trạm biến áp & Lưới điện phân phối', 'Theo dõi thông số vận hành trạm biến áp, phân tích sự cố quá tải, ngắn mạch và lập phương án đóng cắt điện.')], 4: [('Kỹ sư thiết kế hệ thống điện chính thức', 'Chịu trách nhiệm thiết kế toàn bộ hệ thống cung cấp điện trung thế và hạ thế cho khu công nghiệp hoặc tòa nhà cao tầng.'), ('Chuyên gia tư vấn năng lượng tái tạo (Solar/Wind Engineer)', 'Thiết kế hệ thống điện mặt trời áp mái công nghiệp, tính toán sản lượng điện và hiệu quả đầu tư.'), ('Chỉ huy trưởng thi công hệ thống cơ điện (M&E Project Leader)', 'Quản lý tiến độ, chất lượng và an toàn toàn bộ gói thầu cơ điện cho các dự án xây dựng quy mô lớn.')]}}, 'Kỹ thuật điều khiển và tự động hóa': {'discipline': 'lý thuyết điều khiển tự động, vi điều khiển nhúng, lập trình PLC công nghiệp, thiết kế giao diện HMI và hệ thống giám sát SCADA', 'intro': "Kỹ thuật điều khiển và Tự động hóa là trái tim công nghệ của cuộc Cách mạng Công nghiệp 4.0, biến các nhà máy truyền thống thành các nhà máy thông minh (Smart Factories) vận hành hoàn toàn tự động với độ chính xác cao và năng suất vượt trội. Kỹ sư tự động hóa nắm giữ bí quyết làm cho máy móc 'biết nghĩ', biết tự động điều chỉnh tốc độ, nhiệt độ, áp suất theo thuật toán tối ưu mà không cần sự can thiệp thủ công của con người.", 'beginner': 'Người mới bắt đầu cần nắm vững toán học giải tích điều khiển (biến đổi Laplace, hàm truyền đạt), hiểu nguyên lý hoạt động của các cảm biến công nghiệp và rèn luyện kỹ năng lập trình vi điều khiển C căn bản.', 'tools': ['Phần mềm TIA Portal (Siemens)', 'MATLAB / Simulink', 'Phần mềm thiết kế HMI WinCC / FactoryTalk', 'Bộ kit vi điều khiển ARM / STM32'], 'standards': ['Chuẩn lập trình điều khiển IEC 61131-3 (Ladder, FBD, SCL)', 'Giao thức truyền thông công nghiệp Modbus / Profinet / OPC-UA', 'Tiêu chuẩn an toàn máy móc ISO 13849', 'Chuẩn hệ thống SCADA ISA-101'], 'roles': {1: [('Kỹ thuật viên bảo trì thiết bị tự động', 'Kiểm tra cảm biến hành trình, vệ sinh đầu đọc và đấu nối tín hiệu điều khiển vào tủ điện.'), ('Thực tập sinh lập trình vi điều khiển', 'Viết mã C điều khiển động cơ bước, đọc tín hiệu cảm biến quang và hiển thị thông số lên màn hình LCD.'), ('Trợ lý đo kiểm tín hiệu công nghiệp', 'Sử dụng đồng hồ vạn năng và máy hiện sóng (Oscilloscope) để kiểm tra dạng sóng tín hiệu cảm biến.')], 2: [('Lập trình viên PLC tập sự (Junior PLC Programmer)', 'Viết chương trình điều khiển theo chu trình tuần tự bằng ngôn ngữ Ladder cho dây chuyền đóng gói.'), ('Kỹ sư thiết kế giao diện HMI', 'Thiết kế các màn hình điều khiển cảm ứng trực quan: nút bấm, đồng hồ đo, cảnh báo lỗi và biểu đồ nhiệt độ.'), ('Kỹ thuật viên cân chỉnh cảm biến & Thiết bị đo (Instrumentation Tech)', 'Hiệu chuẩn các cảm biến áp suất, lưu lượng kế và van điều khiển khí nén trong nhà máy.')], 3: [('Kỹ sư tự động hóa công nghiệp (Automation Engineer)', 'Lập trình toàn diện hệ thống PLC kết nối HMI và biến tần điều khiển động cơ qua mạng truyền thông Profinet.'), ('Kỹ sư thiết kế hệ thống SCADA', 'Xây dựng phần mềm giám sát SCADA thu thập dữ liệu toàn nhà máy, lưu trữ dữ liệu lịch sử và xuất báo cáo ca sản xuất.'), ('Kỹ sư tích hợp robot công nghiệp tập sự', 'Lập trình quỹ đạo chuyển động cho cánh tay robot gắp sản phẩm và tích hợp cảm biến thị giác máy (Machine Vision).')], 4: [('Kỹ sư trưởng giải pháp tự động hóa (Lead Automation Engineer)', 'Chịu trách nhiệm thiết kế tổng thể kiến trúc tự động hóa cho dây chuyền sản xuất mới của nhà máy.'), ('Chuyên gia tích hợp hệ thống sản xuất thông minh (MES/IIoT Specialist)', 'Kết nối hệ thống SCADA tầng vận hành sản xuất với hệ thống hoạch định ERP tầng quản trị doanh nghiệp.'), ('Chuyên viên tư vấn giải pháp tự động hóa công nghiệp', 'Tư vấn chuyển đổi số nhà máy và giải pháp nâng cấp dây chuyền sản xuất cho các khách hàng công nghiệp.')]}}, 'Kỹ thuật cơ điện tử': {'discipline': 'cơ học kỹ thuật, mô hình hóa 3D chi tiết máy trên SolidWorks, tích hợp cảm biến - vi điều khiển và lập trình robot công nghiệp', 'intro': 'Kỹ thuật cơ điện tử (Mechatronics) là sự giao thoa hài hòa giữa ba trụ cột: Cơ khí chính xác, Điện tử điều khiển và Công nghệ thông tin. Kỹ sư cơ điện tử là những người có năng lực bao quát phi thường: vừa biết tính toán độ bền kết cấu cơ khí, vừa biết thiết kế mạch điện tử điều khiển và lập trình thuật toán thông minh để tạo ra các robot tự hành, thiết bị y tế chính xác và máy bay không người lái (UAV).', 'beginner': 'Lời khuyên cho người mới bắt đầu là làm chủ kỹ thuật dựng hình 3D trên SolidWorks, hiểu rõ nguyên lý truyền động cơ khí (bánh răng, đai, vít me) và kiên trì lắp ráp các mô hình cơ cấu thử nghiệm thực tế.', 'tools': ['SolidWorks', 'AutoCAD Cơ khí', 'Arduino / STM32 IDE', 'MATLAB Robotics Toolbox', 'Phần mềm in 3D Cura'], 'standards': ['Tiêu chuẩn dung sai lắp ghép ISO 286', 'Tiêu chuẩn bản vẽ cơ khí TCVN / ISO', 'Quy chuẩn an toàn robot công nghiệp ISO 10218', 'Tiêu chuẩn linh kiện cơ điện tử'], 'roles': {1: [('Kỹ thuật viên vẽ cơ khí 2D (Mechanical Drafter)', 'Vẽ lại các chi tiết máy đơn giản trên AutoCAD, bóc tách kích thước và ghi chú dung sai gia công.'), ('Thực tập sinh lắp ráp cơ điện tử', 'Gia công cắt gọt vật liệu cơ bản, sử dụng máy in 3D để tạo mẫu cơ cấu và lắp ráp khung robot mini.'), ('Trợ lý phòng thí nghiệm chế tạo mẫu (Maker Lab Assistant)', 'Bảo dưỡng máy in 3D, máy cắt laser và hỗ trợ sinh viên chuẩn bị vật tư dự án.')], 2: [('Chuyên viên thiết kế 3D SolidWorks (Junior CAD/CAM Designer)', 'Dựng mô hình 3D các chi tiết máy phức tạp, lắp ráp cụm cơ cấu và xuất bản vẽ gia công 2D.'), ('Kỹ thuật viên mạch điều khiển nhúng cơ điện tử', 'Thiết kế mạch in PCB trên Altium Designer và hàn linh kiện điều khiển cho động cơ Servo/DC.'), ('Kỹ sư kiểm thử độ tin cậy cơ cấu (Mechanical Test Engineer)', 'Gá đặt cảm biến lực, cảm biến gia tốc để đo độ rung động và độ võng của kết cấu cơ khí.')], 3: [('Kỹ sư cơ điện tử (Mechatronics Engineer)', 'Thiết kế hoàn chỉnh một máy tự động: tính toán công suất động cơ, thiết kế cơ cấu chấp hành và lập trình điều khiển PLC.'), ('Kỹ sư lập trình robot công nghiệp', 'Thiết lập điểm dạy học (Teaching) cho robot công nghiệp 6 bậc tự do, lập trình hàn tự động hoặc đóng pallet.'), ('Kỹ sư mô phỏng động lực học (CAE Simulation Engineer)', 'Phân tích ứng suất tĩnh và biến dạng (FEA) trên SolidWorks Simulation để tối ưu hóa trọng lượng chi tiết máy.')], 4: [('Kỹ sư phát triển sản phẩm cơ điện tử thông minh (R&D Mechatronics)', 'Chủ trì đề tài phát triển thiết bị robot tự hành AGV trong nhà kho hoặc thiết bị y sinh thông minh.'), ('Trưởng nhóm kỹ thuật chế tạo máy (Mechanical Engineering Lead)', 'Quản lý quy trình từ ý tưởng thiết kế, gia công CNC chính xác đến lắp ráp thử nghiệm và xuất xưởng.'), ('Chuyên gia tư vấn chuyển giao công nghệ robot', 'Tư vấn ứng dụng giải pháp tự động hóa bằng robot cho các dây chuyền lắp ráp linh kiện điện tử.')]}}, 'Kỹ thuật xây dựng': {'discipline': 'cơ học kết cấu, thiết kế bản vẽ xây dựng AutoCAD, mô hình thông tin công trình BIM/Revit, bóc tách dự toán và quản lý thi công', 'intro': 'Kỹ thuật xây dựng là ngành nghề kiến tạo nên tầm vóc vật chất của đất nước: từ những cây cầu dây văng kỳ vĩ, những tòa tháp chọc trời đến những khu đô thị hiện đại và hệ thống hạ tầng giao thông huyết mạch. Kỹ sư xây dựng gánh vác trách nhiệm cao cả về sự an toàn tính mạng của hàng ngàn con người thông qua việc tính toán chuẩn xác khả năng chịu lực của kết cấu bê tông cốt thép và chỉ huy thi công chuẩn mực trên đại công trường.', 'beginner': 'Sinh viên năm nhất cần tập trung rèn luyện tư duy không gian, đọc hiểu thành thạo các bản vẽ mặt bằng, mặt cắt và nắm chắc các định luật tĩnh học, sức bền vật liệu cơ sở.', 'tools': ['AutoCAD Xây dựng', 'Autodesk Revit Structure', 'Phần mềm tính toán kết cấu Etabs / SAP2000', 'Phần mềm lập dự toán G8 / F1'], 'standards': ['Quy chuẩn kỹ thuật quốc gia về số liệu điều kiện tự nhiên dùng trong xây dựng QCVN 02', 'Tiêu chuẩn thiết kế kết cấu bê tông cốt thép TCVN 5574', 'Tiêu chuẩn tải trọng và tác động TCVN 2737', 'Quy trình giám sát thi công'], 'roles': {1: [('Họa viên xây dựng 2D (Civil Drafter)', 'Vẽ các bản vẽ kiến trúc cơ sở, chỉnh sửa chi tiết cấu tạo móng, cột, dầm trên AutoCAD.'), ('Thực tập sinh khảo sát hiện trường công trình', 'Hỗ trợ kỹ sư đo đạc cao độ bằng máy thủy bình, máy kinh vĩ và ghi chép số liệu trắc địa.'), ('Trợ lý hồ sơ quản lý chất lượng công trường', 'Sắp xếp phiếu kết quả nén mẫu bê tông, chứng chỉ xuất xưởng vật liệu và biên bản nghiệm thu.')], 2: [('Chuyên viên mô hình hóa BIM kết cấu (BIM Modeler Revit)', 'Dựng mô hình 3D kết cấu móng, dầm, sàn, cột trên Autodesk Revit và xuất bản vẽ thép.'), ('Trợ lý kỹ sư tính toán kết cấu', 'Nhập mô hình hình học tòa nhà vào phần mềm Etabs, gán tải trọng gió và tĩnh tải theo tiêu chuẩn Việt Nam.'), ('Kỹ thuật viên thí nghiệm vật liệu xây dựng', 'Thực hiện thí nghiệm kéo nén cốt thép, đúc mẫu bê tông và thí nghiệm độ sụt tại phòng lab Las-XD.')], 3: [('Kỹ sư thiết kế kết cấu công trình (Structural Engineer)', 'Chạy mô hình phân tích nội lực trên Etabs, tính toán diện tích cốt thép dầm cột và kiểm tra độ võng, vết nứt.'), ('Kỹ sư bóc tách khối lượng & Lập dự toán (QS Engineer)', 'Bóc tách khối lượng bê tông, ván khuôn, cốt thép từ bản vẽ và áp định mức đơn giá lập bảng dự toán chi phí.'), ('Kỹ sư giám sát thi công hiện trường (Site Engineer)', 'Trực tiếp chỉ đạo thi công lắp dựng cốt thép, đổ bê tông và nghiệm thu công việc xây dựng tại công trường.')], 4: [('Chỉ huy phó công trình xây dựng (Site Manager Trainee)', 'Điều phối các tổ đội công nhân, kiểm soát an toàn lao động và quản lý tiến độ thi công toàn công trường.'), ('Kỹ sư kết cấu chủ trì (Senior Structural Engineer)', 'Ký duyệt các bản vẽ thiết kế kỹ thuật thi công, chịu trách nhiệm pháp lý về tính an toàn của kết cấu công trình.'), ('Chuyên gia quản lý dự án xây dựng (Project Management Consultant)', 'Tư vấn quản lý chi phí, đấu thầu và tiến độ dự án cho chủ đầu tư các công trình dân dụng và công nghiệp.')]}}, 'Toán ứng dụng': {'discipline': 'giải tích số trị, mô hình hóa toán học, xác suất thống kê nâng cao, thuật toán tối ưu hóa và lập trình tính toán khoa học với Python/MATLAB', 'intro': 'Toán ứng dụng là cây cầu nối vô hình nhưng đầy quyền năng giữa toán học thuần túy và các bài toán thực tiễn của công nghệ, tài chính, khí tượng thủy văn và kỹ thuật. Trong kỷ nguyên dữ liệu lớn và học máy, các nhà toán học ứng dụng chính là những kiến trúc sư đứng sau các thuật toán dự báo thị trường chứng khoán, thuật toán tối ưu hóa logistics và các mô hình mô phỏng vật lý phức tạp.', 'beginner': 'Lời khuyên cho người mới bắt đầu là luôn tìm kiếm ý nghĩa vật lý và hình học đằng sau mỗi công thức giải tích, rèn luyện kỹ năng biến các phương trình vi phân thành các thuật toán số chạy được trên máy tính.', 'tools': ['MATLAB / Simulink', 'Python (NumPy, SciPy, SymPy)', 'Phần mềm thống kê R', 'LaTeX soạn thảo văn bản toán học'], 'standards': ['Phương pháp giải số giải tích số trị (Runge-Kutta, sai phân hữu hạn)', 'Thuật toán tối ưu hóa Simplex / Kháng cự Gradient', 'Tiêu chuẩn đánh giá sai số số học', 'Mô hình toán học Black-Scholes trong tài chính'], 'roles': {1: [('Thực tập sinh tính toán số liệu khoa học', 'Sử dụng Python/Excel để giải các hệ phương trình tuyến tính và vẽ đồ thị hàm số nhiều chiều.'), ('Trợ lý nghiên cứu mô hình toán học', 'Thu thập số liệu thực nghiệm và hỗ trợ kiểm tra tính hội tụ của các chuỗi số liệu.'), ('Cộng tác viên lập trình tính toán', 'Viết mã hiện thực hóa các phương pháp xấp xỉ số trị cơ bản (phương pháp chia đôi, dây cung, Newton).')], 2: [('Chuyên viên phân tích định lượng tập sự (Junior Quantitative Analyst)', 'Mô hình hóa các chuỗi dữ liệu ngẫu nhiên và phân tích hồi quy phi tuyến.'), ('Lập trình viên mô phỏng thuật toán khoa học', 'Sử dụng MATLAB để mô phỏng các phương trình vi phân mô tả chuyển động cơ học hoặc dòng chảy.'), ('Chuyên viên phân tích thống kê ứng dụng', 'Thực hiện các phân tích đa biến, kiểm định phi tham số và phân tích ANOVA cho các dự án nghiên cứu.')], 3: [('Chuyên viên tối ưu hóa vận hành (Operations Research Specialist)', 'Xây dựng các mô hình quy hoạch tuyến tính và nguyên số để giải quyết bài toán định tuyến xe và xếp lịch.'), ('Kỹ sư tài chính định lượng tập sự (Junior Quant)', 'Xây dựng mô hình định giá quyền chọn và phân tích giá trị chịu rủi ro (Value at Risk - VaR) trên thị trường tài chính.'), ('Nghiên cứu viên thuật toán khoa học dữ liệu', 'Phát triển các thuật toán học máy mới dựa trên cơ sở tối ưu hóa lồi và hình học Riemann.')], 4: [('Chuyên gia mô hình hóa toán học (Mathematical Modeling Specialist)', 'Thiết kế các mô hình toán học dự báo biến đổi khí hậu, dịch tễ học hoặc mô phỏng va chạm kỹ thuật.'), ('Nhà khoa học dữ liệu định lượng cao cấp (Senior Quant Scientist)', 'Phát triển các chiến lược giao dịch tự động thuật toán tần suất cao (HFT) tại các quỹ đầu tư định lượng.'), ('Giảng viên / Nghiên cứu viên toán học ứng dụng', 'Chủ trì các đề tài nghiên cứu toán học tính toán cấp quốc gia và công bố bài báo trên các tạp chí SIAM/IEEE.')]}}, 'Công nghệ sinh học': {'discipline': 'sinh học phân tử, kỹ thuật phản ứng chuỗi polymerase PCR, công nghệ nuôi cấy mô tế bào thực vật, công nghệ lên men vi sinh và an toàn sinh học', 'intro': 'Công nghệ sinh học là ngành khoa học mũi nhọn của thế kỷ 21, ứng dụng các cơ chế sinh học của vi sinh vật, thực vật và động vật để tạo ra các giải pháp đột phá trong y dược, nông nghiệp công nghệ cao và bảo vệ môi trường. Từ việc sản xuất vắc-xin cứu sống hàng triệu người, nhân giống cây trồng sạch bệnh đến xử lý ô nhiễm sinh học, kỹ sư công nghệ sinh học là những người kiến tạo sự sống và phát triển bền vững.', 'beginner': 'Nguyên tắc cao nhất trong phòng thí nghiệm sinh học là vô trùng và an toàn: phải luôn tuân thủ quy tắc khử trùng dụng cụ, thao tác chuẩn xác bên trong tủ cấy vô trùng và trung thực với số liệu thực nghiệm.', 'tools': ['Máy luân nhiệt PCR & Real-time PCR', 'Hệ thống điện di gel agarose / Polyacrylamide', 'Tủ cấy vô trùng Laminar Flow', 'Nồi hấp tiệt trùng Autoclave & Kính hiển vi quang học'], 'standards': ['Quy chuẩn an toàn sinh học phòng thí nghiệm cấp 1/2/3', 'Tiêu chuẩn Thực hành sản xuất tốt vi sinh GMP', 'Quy trình vô trùng cấy mô thực vật', 'Đạo đức sinh học trong nghiên cứu'], 'roles': {1: [('Kỹ thuật viên phòng thí nghiệm vi sinh cơ sở', 'Hỗ trợ pha chế môi trường dinh dưỡng, hấp tiệt trùng dụng cụ và nuôi cấy vi khuẩn chỉ thị.'), ('Thực tập sinh nuôi cấy mô thực vật', 'Cắt tỉa mẫu cây con trong tủ cấy vô trùng, theo dõi sự tạo chồi và chuyển môi trường sinh trưởng.'), ('Cộng tác viên ghi chép số liệu phòng lab', 'Đo đạc chỉ tiêu sinh trưởng của cây trồng (chiều cao, số lá) và bảo quản mẫu sinh học trong tủ đông sâu.')], 2: [('Kỹ thuật viên sinh học phân tử (Molecular Lab Tech)', 'Thực hiện tách chiết DNA/RNA từ mẫu lá cây hoặc mô bệnh phẩm, đo nồng độ axit nucleic bằng máy quang phổ.'), ('Kỹ thuật viên vận hành máy PCR', 'Pha hỗn hợp phản ứng PCR, cài đặt chu trình nhiệt và thực hiện điện di gel kiểm tra kích thước đoạn gen khuếch đại.'), ('Chuyên viên kiểm soát chất lượng giống cấy mô', 'Đánh giá tỷ lệ sống, phát hiện hiện tượng tạp nhiễm nấm khuẩn và sàng lọc các dòng đột biến.')], 3: [('Kỹ sư công nghệ lên men vi sinh (Bioprocess Engineer)', 'Vận hành hệ thống bồn lên men công nghiệp (Bioreactor), kiểm soát các thông số pH, nhiệt độ, oxy hòa tan DO.'), ('Chuyên viên phân tích dữ liệu sinh học (Bioinformatician)', 'Sử dụng công cụ BLAST tra cứu trình tự gen trên ngân hàng dữ liệu NCBI, thiết kế mồi PCR (Primer Design).'), ('Chuyên viên nghiên cứu & phát triển sinh học (R&D Specialist)', 'Thử nghiệm các công thức môi trường nuôi cấy mới và tối ưu hóa quy trình chiết xuất hoạt chất sinh học.')], 4: [('Trưởng phòng thí nghiệm công nghệ sinh học (Lab Supervisor)', 'Quản lý toàn bộ hoạt động phòng lab, kiểm soát chất lượng kết quả phân tích và đào tạo kỹ thuật viên.'), ('Kỹ sư chủ trì đề tài vắc-xin / Chế phẩm sinh học', 'Phát triển quy trình sản xuất thương mại cho các loại phân bón sinh học, thuốc trừ sâu sinh học hoặc kit chẩn đoán bệnh.'), ('Chuyên gia tư vấn an toàn sinh học & Sở hữu trí tuệ', 'Tư vấn thủ tục đăng ký bảo hộ giống cây trồng mới và đánh giá tác động môi trường của sinh vật biến đổi gen (GMO).')]}}, 'Công nghệ thực phẩm': {'discipline': 'hóa học thực phẩm, vi sinh vật thực phẩm, quy trình chế biến công nghiệp, kiểm soát chất lượng QC, an toàn thực phẩm HACCP và phát triển sản phẩm mới R&D', 'intro': 'Công nghệ thực phẩm là ngành kỹ thuật đa ngành bảo đảm an ninh lương thực và nâng cao chất lượng cuộc sống con người thông qua việc chế biến, bảo quản và phát triển các sản phẩm thực phẩm an toàn, tiện lợi và giàu giá trị dinh dưỡng. Trong thời đại người tiêu dùng ngày càng quan tâm đến sức khỏe, kỹ sư công nghệ thực phẩm chính là những chuyên gia đứng sau các sản phẩm thực phẩm hữu cơ, đồ uống chức năng và các dây chuyền chế biến tự động đạt chuẩn quốc tế.', 'beginner': 'Người mới bắt đầu cần nắm vững tính chất hóa sinh của các thành phần thực phẩm (carbohydrate, protein, lipid), hiểu rõ vai trò của vi sinh vật có lợi trong lên men cũng như các loài vi sinh vật gây ngộ độc để xây dựng ý thức an toàn thực phẩm nghiêm ngặt.', 'tools': ['Máy đo pH, khúc xạ kế đo độ ngọt Brix', 'Hệ thống phân tích đạm Kjeldahl & Béo Soxhlet', 'Bộ dụng cụ đánh giá cảm quan thực phẩm', 'Phần mềm thiết kế nhãn dinh dưỡng'], 'standards': ['Hệ thống phân tích mối nguy và điểm kiểm soát tới hạn HACCP', 'Tiêu chuẩn hệ thống quản lý an toàn thực phẩm ISO 22000', 'Tiêu chuẩn thực phẩm quốc tế Codex', 'Quy chuẩn kỹ thuật quốc gia về phụ gia thực phẩm QCVN'], 'roles': {1: [('Kỹ thuật viên kiểm tra chất lượng nguyên liệu (IQC Intern)', 'Lấy mẫu nông sản đầu vào, kiểm tra cảm quan độ tươi và đo các chỉ tiêu cơ bản như độ ẩm, độ Brix.'), ('Thực tập sinh chế biến thực phẩm phòng lab', 'Hỗ trợ chuẩn bị nguyên liệu thực hành, vận hành máy sấy, máy ép nước trái cây quy mô nhỏ.'), ('Cộng tác viên kiểm nghiệm vi sinh thực phẩm', 'Đổ đĩa thạch vi sinh, cấy mẫu thực phẩm kiểm tra tổng số vi khuẩn hiếu khí và nấm men nấm mốc.')], 2: [('Chuyên viên kiểm soát chất lượng trên dây chuyền (IPQC Executive)', 'Giám sát các thông số kỹ thuật chế biến (nhiệt độ thanh trùng, áp suất đóng nắp) tại các công đoạn sản xuất.'), ('Kỹ thuật viên phân tích hóa nghiệm thực phẩm', 'Đo hàm lượng đường khử, độ chua tổng số, hàm lượng tro và xác định hàm lượng protein theo phương pháp Kjeldahl.'), ('Trợ lý nghiên cứu phát triển sản phẩm thực phẩm (R&D Assistant)', 'Thực hiện các mẻ nấu thử nghiệm công thức đồ uống hoặc bánh kẹo mới theo hướng dẫn của kỹ sư R&D chính.')], 3: [('Kỹ sư quản lý an toàn thực phẩm (HACCP/ISO Specialist)', 'Xây dựng kế hoạch HACCP, xác định các điểm kiểm soát tới hạn CCP trên dây chuyền và tổ chức diễn tập thu hồi sản phẩm lỗi.'), ('Chuyên viên nghiên cứu & phát triển sản phẩm (Food R&D Specialist)', 'Sáng tạo công thức thực phẩm mới, lựa chọn phụ gia thực phẩm an toàn và thử nghiệm kéo dài thời hạn bảo quản (Shelf-life).'), ('Chuyên viên điều phối hội đồng đánh giá cảm quan', 'Thiết kế các phép thử cảm quan (phép thử tam giác, phép thử cho điểm thị hiếu) và xử lý thống kê mức độ ưa chuộng của người tiêu dùng.')], 4: [('Trưởng phòng đảm bảo chất lượng nhà máy (QA Manager Trainee)', 'Chịu trách nhiệm toàn diện về chất lượng và an toàn thực phẩm của toàn bộ nhà máy chế biến xuất khẩu.'), ('Chuyên gia chuyển giao công nghệ chế biến thực phẩm', 'Thiết kế và tối ưu hóa dây chuyền chế biến công nghiệp từ quy mô phòng thí nghiệm lên quy mô nhà máy (Scale-up).'), ('Chuyên viên tư vấn chứng nhận tiêu chuẩn thực phẩm quốc tế', 'Tư vấn và đánh giá chứng nhận hệ thống FSSC 22000, BRC hoặc chứng nhận Halal cho các doanh nghiệp xuất khẩu.')]}}, 'Thương mại điện tử': {'discipline': 'kinh tế số, vận hành sàn thương mại điện tử đa kênh, tối ưu hóa tỷ lệ chuyển đổi và quản trị trải nghiệm khách hàng', 'intro': 'Ngành Thương mại điện tử là động lực tăng trưởng hàng đầu của nền kinh tế số. Năm thứ nhất là giai đoạn người học chuyển dịch từ tư duy của một người mua sắm thông thường sang tư duy của một nhà vận hành kinh doanh: hiểu rõ cách thức dòng tiền, dòng hàng và dòng thông tin vận động trong các mô hình B2C, B2B, D2C.', 'beginner': 'Đối với người mới bắt đầu, việc thành thạo kỹ năng xử lý số liệu bán hàng trên Excel và nắm vững quy trình xử lý đơn hàng từ lúc khách bấm mua đến khi giao nhận thành công là nền tảng không thể thiếu.', 'tools': ['Kênh Người bán Shopee / TikTok Shop Seller', 'Google Analytics 4', 'Phần mềm quản lý bán hàng đa kênh Haravan/Sapo', 'Canva / CapCut'], 'standards': ['Quy chuẩn SEO sàn TMĐT', 'Mô hình phễu chuyển đổi AARRR', 'Chỉ số hoàn vốn quảng cáo ROAS / ACOS', 'Luật An toàn thông tin mạng & Thuế thương mại điện tử'], 'roles': {1: [('Cộng tác viên vận hành sàn TMĐT (Operations Assistant)', 'Hỗ trợ đăng tải sản phẩm, quản lý tồn kho và xử lý đơn hàng hàng ngày.'), ('Thực tập sinh quản lý đơn hàng & Kho vận số', 'Theo dõi trạng thái giao hàng, đối soát COD và xử lý khiếu nại hoàn tiền.'), ('Nhân viên chăm sóc khách hàng trực tuyến', 'Tư vấn sản phẩm trên khung chat sàn, giải đáp thắc mắc về vận chuyển và khuyến mãi.')], 2: [('Chuyên viên SEO sàn thương mại điện tử (SEO Specialist)', 'Nghiên cứu từ khóa, tối ưu hóa tiêu đề và nội dung sản phẩm nhằm tăng thứ hạng tự nhiên.'), ('Chuyên viên phân tích dữ liệu web (Web Analytics Executive)', 'Theo dõi lưu lượng truy cập, phân tích phễu chuyển đổi và thiết lập đo lường trên GA4.'), ('Chuyên viên tối ưu hóa tỷ lệ chuyển đổi (CRO Executive)', 'Thực hiện A/B testing, đánh giá trải nghiệm người dùng và đề xuất cải tiến trang đích.')], 3: [('Trưởng nhóm vận hành gian hàng sàn (E-commerce Store Leader)', 'Chịu trách nhiệm doanh số gian hàng, lập kế hoạch chiến dịch sale và điều phối nhân sự.'), ('Chuyên viên quản trị quan hệ khách hàng (CRM Executive)', 'Xây dựng kịch bản tiếp thị tự động hóa, phân khúc dữ liệu khách hàng và triển khai chương trình loyalty.'), ('Chuyên viên hoạch định bán hàng đa kênh (Omnichannel Specialist)', 'Đồng bộ hóa tồn kho, tối ưu hóa quy trình hoàn tất đơn hàng và phân tích chi phí vận hành.')], 4: [('Chuyên viên phát triển kinh doanh thương mại điện tử (E-commerce BD)', 'Tìm kiếm đối tác, phát triển ngành hàng và mở rộng kênh phân phối trực tuyến.'), ('Quản lý ngành hàng sàn TMĐT tập sự (Junior Category Manager)', 'Quản lý doanh số danh mục ngành hàng, đàm phán chương trình độc quyền với các thương hiệu lớn.'), ('Chuyên viên tư vấn tăng trưởng thương mại số (E-commerce Growth Specialist)', 'Tối ưu hóa toàn diện phễu chuyển đổi, ngân sách quảng cáo và chiến lược giữ chân khách hàng.')]}}, 'Quản trị rủi ro': {'discipline': 'quản trị rủi ro doanh nghiệp (ERM), hệ thống kiểm soát nội bộ (COSO), kiểm toán tài chính và phân tích an toàn vốn', 'intro': 'Quản trị rủi ro và Kiểm toán là lá chắn bảo vệ tài sản và uy tín của doanh nghiệp trước những biến động khôn lường của thị trường tài chính và các gian lận nội bộ. Việc xây dựng một hệ thống kiểm soát nội bộ vững chắc giúp tổ chức phát hiện sớm các nguy cơ mất khả năng thanh toán, vi phạm pháp lý và tổn thất hoạt động.', 'beginner': 'Người mới bắt đầu cần làm chủ kỹ năng đọc hiểu báo cáo tài chính, hiểu rõ cấu trúc khung kiểm soát nội bộ COSO và thành thạo các kỹ thuật phân tích số liệu trên Excel.', 'tools': ['Microsoft Excel kiểm toán nâng cao', 'Phần mềm kiểm toán IDEA / ACL', 'Mô hình chấm điểm rủi ro', 'Phần mềm phân tích báo cáo tài chính FiinPro'], 'standards': ['Khung quản trị rủi ro doanh nghiệp COSO ERM 2017', 'Chuẩn mực kiểm toán Việt Nam (VSA)', 'Tiêu chuẩn quản trị rủi ro ISO 31000', 'Hiệp ước Basel II/III'], 'roles': {1: [('Thực tập sinh kiểm soát rủi ro cơ sở', 'Hỗ trợ thu thập tài liệu quy trình, lập bảng kiểm tra tuân thủ và nhập liệu hồ sơ kiểm toán.'), ('Trợ lý phân tích dữ liệu tài chính', 'Tính toán các tỷ số thanh khoản, đòn bẩy tài chính và đối chiếu số liệu sổ sách kế toán.'), ('Cộng tác viên kiểm kê tài sản nội bộ', 'Tham gia các đợt kiểm kê tiền mặt, hàng tồn kho và tài sản cố định định kỳ.')], 2: [('Chuyên viên kiểm soát nội bộ tập sự (Junior Internal Controller)', 'Đánh giá hiệu lực của các biện pháp kiểm soát phân quyền phê duyệt chi tiêu và mua sắm.'), ('Chuyên viên phân tích rủi ro hoạt động (Operational Risk Analyst)', 'Thu thập dữ liệu các sự kiện tổn thất vận hành và xây dựng ma trận đánh giá rủi ro.'), ('Trợ lý kiểm toán viên tài chính', 'Thực hiện các thủ tục phân tích cơ bản và kiểm tra chi tiết số dư tài khoản tiền gửi, công nợ.')]}}, 'Kinh tế': {'discipline': 'kinh tế vi mô - vĩ mô, mô hình hóa kinh tế lượng, phân tích chuỗi dữ liệu thời gian, dự báo xu hướng thị trường và chính sách công', 'intro': 'Ngành Kinh tế cung cấp lăng kính khoa học để giải mã các quy luật vận động của thị trường, hành vi của các tác nhân kinh tế và tác động của các chính sách tiền tệ, tài khóa quốc gia. Kỹ năng mô hình hóa kinh tế lượng và năng lực xử lý số liệu lớn giúp các nhà kinh tế học đưa ra những dự báo chuẩn xác và khuyến nghị chính sách có sức ảnh hưởng sâu rộng.', 'beginner': 'Sinh viên năm nhất cần xây dựng tư duy phân tích cận biên (Marginal Thinking), hiểu rõ nguyên lý cân bằng cung cầu và thành thạo các hàm thống kê trên Excel trước khi tiếp cận các mô hình kinh tế lượng phức tạp.', 'tools': ['Phần mềm kinh tế lượng Stata / EViews', 'Microsoft Excel phân tích kinh tế', 'Ngôn ngữ R phân tích dữ liệu', 'Cơ sở dữ liệu kinh tế vĩ mô Tổng cục Thống kê / World Bank'], 'standards': ['Phương pháp ước lượng OLS', 'Kiểm định hiện tượng đa cộng tuyến, phương sai thay đổi', 'Mô hình hồi quy chuỗi thời gian ARIMA', 'Nguyên lý kinh tế học Mankiw'], 'roles': {1: [('Thực tập sinh nghiên cứu kinh tế cơ sở', 'Thu thập số liệu GDP, lạm phát, CPI từ Tổng cục Thống kê và vẽ biểu đồ biến động theo năm.'), ('Trợ lý phân tích dữ liệu thị trường', 'Làm sạch số liệu khảo sát giá cả hàng hóa tiêu dùng và tính toán các chỉ số thống kê mô tả.'), ('Cộng tác viên khảo sát kinh tế thực địa', 'Thực hiện phỏng vấn người dân và doanh nghiệp theo bảng hỏi điều tra kinh tế xã hội.')], 2: [('Chuyên viên nghiên cứu kinh tế vĩ mô tập sự', 'Phân tích tác động của lãi suất điều hành và tỷ giá đến xuất nhập khẩu và tăng trưởng kinh tế.'), ('Chuyên viên phân tích kinh tế lượng (Econometric Analyst)', 'Xây dựng các mô hình hồi quy OLS, kiểm định các khuyết tật của mô hình và chạy dự báo trên Stata/EViews.'), ('Chuyên viên tư vấn chính sách kinh tế', 'Soạn thảo các báo cáo tóm tắt phân tích thị trường ngành phục vụ các hiệp hội doanh nghiệp.')]}}, 'Kinh doanh số và trí tuệ nhân tạo': {'discipline': 'mô hình kinh doanh số, phân tích nghiệp vụ BA ứng dụng AI, tự động hóa quy trình bằng Python và thiết kế giải pháp chuyển đổi số', 'intro': 'Kinh doanh số và Trí tuệ nhân tạo là ngành học tiên phong đào tạo thế hệ nhà quản trị kinh doanh am hiểu sâu sắc về công nghệ và AI. Trong bối cảnh mọi ngành nghề đều tái cấu trúc mô hình kinh doanh quanh các thuật toán số, người sở hữu cả tư duy kinh doanh và kỹ năng ứng dụng Python/AI chính là những người dẫn dắt các dự án chuyển đổi số đột phá.', 'beginner': 'Người mới bắt đầu cần làm quen với tư duy thuật toán thông qua Python, hiểu cách thức các nền tảng số tạo ra hiệu ứng mạng lưới (Network Effects) và thành thạo phân tích dữ liệu kinh doanh trên bảng tính.', 'tools': ['Python (Pandas, Scikit-learn)', 'Microsoft Excel nâng cao', 'Figma thiết kế giải pháp số', 'Công cụ AI tạo sinh doanh nghiệp (ChatGPT Enterprise, Claude)'], 'standards': ['Khung thiết kế mô hình kinh doanh Business Model Canvas (BMC)', 'Tiêu chuẩn phân tích nghiệp vụ BABOK', 'Khung đạo đức ứng dụng AI trong doanh nghiệp', 'Phương pháp tư duy thiết kế Design Thinking'], 'roles': {1: [('Thực tập sinh kinh doanh số cơ sở', 'Khảo sát các ứng dụng số của đối thủ, trải nghiệm dịch vụ khách hàng số và lập bảng đối sánh tính năng.'), ('Trợ lý số hóa dữ liệu doanh nghiệp', 'Chuẩn hóa các biểu mẫu nghiệp vụ từ giấy tờ sang bảng tính số và hỗ trợ chuyển đổi dữ liệu.'), ('Cộng tác viên ứng dụng AI văn phòng', 'Thử nghiệm các công cụ AI tạo sinh để hỗ trợ soạn thảo email, tóm tắt biên bản họp và dịch tài liệu.')], 2: [('Chuyên viên phân tích nghiệp vụ số (Digital BA)', 'Mô hình hóa quy trình kinh doanh To-Be có ứng dụng tự động hóa và viết tài liệu đặc tả User Story.'), ('Chuyên viên phát triển giải pháp AI kinh doanh', 'Ứng dụng Python để tự động hóa việc thu thập giá thị trường và phân tích tâm lý khách hàng từ mạng xã hội.'), ('Điều phối viên dự án chuyển đổi số', 'Theo dõi tiến độ triển khai các công cụ số nội bộ (CRM, ERP, Chatbot) và hỗ trợ đào tạo người dùng cuối.')]}}, 'Quản trị nhân lực': {'discipline': 'quản trị nguồn nhân lực, tuyển dụng và thu hút nhân tài, đào tạo phát triển, quan hệ lao động, tiền lương phúc lợi C&B và hành chính văn phòng', 'intro': 'Quản trị nhân lực là nghệ thuật tìm kiếm, nuôi dưỡng và gắn kết nguồn lực quý giá nhất của mọi tổ chức - Con người. Một chuyên gia nhân sự hiện đại không chỉ làm thủ tục hành chính mà là đối tác chiến lược của doanh nghiệp (HRBP), kiến tạo môi trường làm việc hạnh phúc, thu hút những nhân tài xuất sắc nhất và xây dựng văn hóa doanh nghiệp vững mạnh.', 'beginner': 'Sinh viên năm nhất cần bắt đầu từ việc chuẩn hóa kỹ năng soạn thảo văn bản hành chính quy chuẩn theo Nghị định 30, hiểu các nguyên tắc giao tiếp công sở văn minh và làm chủ Excel để xử lý dữ liệu chấm công, tính lương.', 'tools': ['Microsoft Excel chuyên sâu nhân sự (bảng lương, chấm công)', 'Phần mềm quản trị nhân sự HRM (Base.vn, 1Office)', 'Mạng tuyển dụng LinkedIn / TopCV', 'Phần mềm lưu trữ hồ sơ điện tử'], 'standards': ['Bộ luật Lao động 2019', 'Luật Bảo hiểm xã hội', 'Nghị định 30/2020/NĐ-CP về công tác văn thư', 'Mô hình năng lực nhân sự ASK (Attitude-Skill-Knowledge)'], 'roles': {1: [('Thực tập sinh hành chính văn phòng (Office Admin Intern)', 'Soạn thảo thông báo nội bộ, sắp xếp hồ sơ nhân sự, quản lý văn phòng phẩm và hỗ trợ hậu cần sự kiện.'), ('Cộng tác viên tuyển dụng cơ sở (Recruitment Sourcing Assistant)', 'Đăng tin tuyển dụng trên các hội nhóm, sàng lọc CV thô và liên hệ ứng viên hẹn lịch phỏng vấn.'), ('Trợ lý nhập liệu hồ sơ nhân sự', 'Cập nhật thông tin nhân viên mới vào phần mềm HRM và kiểm tra tính đầy đủ của hồ sơ lý lịch.')], 2: [('Chuyên viên tuyển dụng tập sự (Junior Recruiter)', 'Trực tiếp phỏng vấn sơ loại ứng viên, điều phối quy trình tuyển dụng và chăm sóc trải nghiệm ứng viên.'), ('Chuyên viên tiền lương & Phúc lợi tập sự (C&B Specialist)', 'Thực hiện chấm công hàng tháng, tính toán các khoản trích bảo hiểm xã hội, thuế TNCN và lập bảng lương.'), ('Chuyên viên truyền thông nội bộ & Gắn kết (Internal Comms Officer)', 'Sáng tạo nội dung bản tin nội bộ, tổ chức các hoạt động kỷ niệm, sinh nhật và team building cho nhân viên.')]}}, 'Luật': {'discipline': 'lý luận nhà nước và pháp luật, tra cứu văn bản quy phạm pháp luật, pháp luật doanh nghiệp, hợp đồng thương mại và tư vấn pháp lý', 'intro': 'Ngành Luật là nền tảng bảo đảm sự thượng tôn pháp luật, duy trì trật tự kỷ cương xã hội và bảo vệ quyền và lợi ích hợp pháp của các cá nhân, tổ chức. Cử nhân ngành Luật được tôi luyện tư duy pháp lý sắc bén, khả năng phân tích sự kiện dưới lăng kính quy phạm và kỹ năng tranh luận, bảo vệ lẽ phải trên tinh thần công lý.', 'beginner': 'Sinh viên năm nhất cần xây dựng thói quen tra cứu văn bản quy phạm pháp luật trên Cổng thông tin điện tử Chính phủ, hiểu thứ bậc hiệu lực pháp lý của các văn bản và rèn luyện kỹ năng viết câu văn pháp lý chặt chẽ, gãy gọn.', 'tools': ['Cơ sở dữ liệu văn bản pháp luật LuatVietnam / ThuVienPhapLuat', 'Hệ thống quản lý án lệ Tòa án nhân dân tối cao', 'Mẫu văn bản tố tụng tư pháp', 'Phần mềm rà soát văn bản pháp lý'], 'standards': ['Hiến pháp 2013', 'Luật Ban hành văn bản quy phạm pháp luật', 'Bộ luật Dân sự 2015', 'Quy tắc đạo đức và ứng xử nghề nghiệp luật sư Việt Nam'], 'roles': {1: [('Thực tập sinh nghiên cứu văn bản pháp luật cơ sở', 'Hỗ trợ tra cứu các nghị định, thông tư hướng dẫn thi hành và lập bảng so sánh điểm mới của luật sửa đổi.'), ('Trợ lý văn phòng luật sư', 'Tiếp nhận đơn từ yêu cầu tư vấn, sắp xếp hồ sơ vụ việc pháp lý và soạn thảo giấy mời, công văn hành chính.'), ('Cộng tác viên rà soát tính hợp pháp của tài liệu', 'Kiểm tra tính đầy đủ của chữ ký, con dấu và tư cách pháp nhân trên các biên bản thỏa thuận.')], 2: [('Chuyên viên tư vấn pháp lý sơ cấp (Junior Legal Advisor)', 'Tư vấn thủ tục đăng ký kinh doanh, thủ tục cấp giấy phép hoạt động và soạn thảo các đơn yêu cầu hành chính.'), ('Trợ lý soạn thảo hợp đồng kinh tế', 'Soạn thảo các dự thảo hợp đồng mua bán, thuê tài sản theo mẫu và rà soát các điều khoản miễn trừ trách nhiệm.'), ('Thư ký phiên họp giải quyết tranh chấp', 'Ghi biên bản thương lượng hòa giải giữa các bên tranh chấp và chuẩn bị hồ sơ khởi kiện tại Tòa án.')]}}, 'Kỹ thuật cơ khí': {'discipline': 'cơ học kỹ thuật, phương pháp đọc bản vẽ kỹ thuật cơ khí, thiết kế 2D AutoCAD, mô hình hóa 3D SolidWorks, nguyên lý máy và gia công cơ khí chính xác', 'intro': 'Kỹ thuật cơ khí là ngành kỹ thuật nền tảng của mọi ngành công nghiệp chế tạo, chịu trách nhiệm thiết kế, chế tạo và vận hành mọi loại máy móc, từ động cơ ô tô, dây chuyền sản xuất đến các kết cấu hàng không vũ trụ. Kỹ sư cơ khí biến những thanh thép thô sơ thành những cỗ máy chính xác vận hành êm ái nhờ sự am hiểu sâu sắc về độ bền vật liệu, truyền động cơ cấu và công nghệ gia công kim loại.', 'beginner': 'Sinh viên năm nhất cần làm chủ ngôn ngữ giao tiếp của ngành cơ khí - đó là Bản vẽ kỹ thuật: rèn luyện trí tưởng tượng hình học họa hình, hiểu các quy ước hình chiếu, mặt cắt và ký hiệu dung sai theo tiêu chuẩn ISO.', 'tools': ['AutoCAD Cơ khí', 'SolidWorks 3D CAD/CAM', 'Thước cặp cơ khí / Panme đo chính xác', 'Phần mềm mô phỏng gia công CNC Mastercam'], 'standards': ['Tiêu chuẩn bản vẽ cơ khí TCVN / ISO 128', 'Hệ thống dung sai lắp ghép ISO 286', 'Tiêu chuẩn vật liệu kim loại JIS / ASTM', 'Quy trình an toàn xưởng cơ khí'], 'roles': {1: [('Họa viên thiết kế cơ khí 2D (Mechanical Drafter)', 'Vẽ chi tiết máy từ phác thảo tay lên AutoCAD, thể hiện đúng kích thước và các hình chiếu.'), ('Thực tập sinh đo kiểm cơ khí chính xác', 'Sử dụng thước cặp, panme, đồng hồ so để kiểm tra kích thước chi tiết sau gia công nguội.'), ('Cộng tác viên thực hành nguội & Hàn cơ bản', 'Thực hành dũa, cưa, khoan kim loại và nắm vững các quy tắc an toàn bảo hộ lao động xưởng máy.')], 2: [('Kỹ sư mô hình hóa 3D SolidWorks (CAD Modeler)', 'Dựng mô hình 3D chi tiết máy phức tạp, tạo cụm lắp ráp động học (Assembly) và kiểm tra va chạm.'), ('Kỹ sư công nghệ gia công cơ khí tập sự', 'Lập quy trình công nghệ gia công chi tiết (tiện, phay, bào), chọn dao cụ và chế độ cắt hợp lý.'), ('Kỹ thuật viên lập trình máy công cụ CNC', 'Viết mã G-code lập trình gia công phay/tiện CNC trên phần mềm CAM và gá đặt phôi trên máy thực tế.')]}}, 'Kỹ thuật hóa học': {'discipline': 'hóa học đại cương và vô cơ/hữu cơ, quy tắc an toàn hóa chất, phương pháp phân tích hóa học hiện đại, kiểm soát chất lượng QC và công nghệ vật liệu', 'intro': 'Kỹ thuật hóa học và Vật liệu là ngành kỹ thuật biến đổi các nguyên liệu thô trong tự nhiên thành các sản phẩm hóa học, vật liệu polyme, composite, dược phẩm và năng lượng sạch phục vụ đời sống. Từ việc sản xuất hạt nhựa tái sinh, pin lithium-ion cho xe điện đến tổng hợp các màng lọc nano, kỹ sư hóa học là những nhà biến đổi vật chất mang lại giá trị gia tăng khổng lồ cho nền công nghiệp.', 'beginner': 'Nguyên tắc số một là An toàn hóa chất: luôn mang kính bảo hộ, áo blouse, găng tay, nắm rõ bảng chỉ dẫn an toàn hóa chất (MSDS) và xử lý sự cố tràn đổ hóa chất trước khi làm bất kỳ thí nghiệm nào.', 'tools': ['Máy quang phổ UV-VIS', 'Hệ thống sắc ký lỏng HPLC / Khí GC', 'Cân phân tích điện tử độ chính xác 4 số', 'Thiết bị đo độ nhớt, đo pH phòng lab'], 'standards': ['Hệ thống hài hòa toàn cầu về phân loại và ghi nhãn hóa chất GHS', 'Bảng chỉ dẫn an toàn hóa chất MSDS', 'Tiêu chuẩn phòng thử nghiệm ISO/IEC 17025', 'Quy định quản lý chất thải nguy hại'], 'roles': {1: [('Kỹ thuật viên phòng thí nghiệm hóa học cơ sở', 'Pha chế dung dịch chuẩn độ, chuẩn bị hóa chất thực hành và vệ sinh dụng cụ thủy tinh.'), ('Thực tập sinh an toàn hóa chất & Lưu kho', 'Kiểm tra nhãn mác hóa chất theo chuẩn GHS, sắp xếp hóa chất theo tính tương thích và kiểm tra hạn dùng.'), ('Cộng tác viên ghi chép thực nghiệm hóa học', 'Cân đong mẫu thử, đo chỉ số pH, tỷ trọng dung dịch và ghi nhật ký phân tích vào sổ tay phòng lab.')], 2: [('Kỹ thuật viên phân tích hóa nghiệm (QC Lab Tech)', 'Vận hành máy đo quang phổ UV-Vis, thực hiện phép chuẩn độ axit-bazơ xác định hàm lượng hoạt chất.'), ('Kỹ sư kiểm soát chất lượng vật liệu tập sự', 'Đo kiểm độ bền kéo đứt, độ đàn hồi của mẫu vật liệu polyme/cao su trên máy kéo nén vạn năng.'), ('Kỹ sư công nghệ hóa chất tập sự (Process Tech)', 'Theo dõi thông số nhiệt độ, áp suất của tháp chưng cất hoặc bồn phản ứng trong dây chuyền sản xuất.')]}}, 'Kiến trúc': {'discipline': 'hình học họa hình, mỹ thuật tạo hình không gian, thể hiện ý tưởng với AutoCAD và SketchUp, mô hình thông tin công trình BIM và giải pháp kiến trúc', 'intro': 'Kiến trúc là sự kết hợp kỳ diệu giữa nghệ thuật tạo hình không gian và khoa học kỹ thuật xây dựng, nhằm kiến tạo nên những công trình vừa có giá trị thẩm mỹ thăng hoa vừa đáp ứng công năng sử dụng tiện nghi, an toàn và bền vững cho con người. Một kiến trúc sư tài ba không chỉ vẽ nên những phối cảnh tráng lệ mà còn là người thấu hiểu vi khí hậu, vật liệu bản địa và tâm lý người sống trong không gian đó.', 'beginner': 'Người mới bắt đầu cần rèn luyện năng lực tư duy không gian 3 chiều, vẽ phác thảo tay bằng bút sắt và màu nước để truyền tải cảm xúc trước khi lệ thuộc vào các phần mềm dựng hình máy tính.', 'tools': ['AutoCAD Kiến trúc', 'SketchUp / Enscape render', 'Autodesk Revit Architecture (BIM)', 'Adobe Photoshop kiến trúc', 'Bàn cắt mô hình kiến trúc'], 'standards': ['Quy chuẩn kỹ thuật quốc gia về quy hoạch xây dựng QCVN 01', 'Tiêu chuẩn thiết kế nhà ở dân dụng TCVN', 'Tiêu chuẩn thiết kế công trình xanh Lotus / LEED', 'Mức độ phát triển mô hình BIM LOD'], 'roles': {1: [('Họa viên kiến trúc 2D (Architectural Drafter)', 'Triển khai bản vẽ mặt bằng, mặt đứng, mặt cắt công trình nhà ở gia đình trên AutoCAD.'), ('Thực tập sinh làm mô hình kiến trúc thủ công', 'Cắt dán mô hình kiến trúc tỷ lệ 1:100 bằng bìa mô hình, gỗ balsa phục vụ thuyết trình đồ án.'), ('Trợ lý khảo sát hiện trạng công trình', 'Chụp ảnh hiện trạng khu đất, đo đạc kích thước thực tế công trình cải tạo và ghi chép nhật ký khảo sát.')], 2: [('Chuyên viên diễn họa kiến trúc 3D (3D Architectural Visualizer)', 'Dựng phối cảnh 3D công trình trên SketchUp, thiết lập vật liệu, ánh sáng và render ảnh bằng Enscape.'), ('Chuyên viên mô hình hóa kiến trúc BIM (BIM Modeler Revit)', 'Dựng mô hình thông tin kiến trúc trên Revit, tạo các cấu kiện tường, cửa, mái và bóc tách bảng thống kê.'), ('Trợ lý kiến trúc sư ý tưởng (Concept Architect Assistant)', 'Tìm kiếm ý tưởng thiết kế (Moodboard), phân tích vị trí khu đất và đề xuất các phương án bố trí mặt bằng công năng.')]}}, 'Toán học': {'discipline': 'phương pháp luận nghiên cứu khoa học cơ bản, thiết kế thí nghiệm, thống kê ứng dụng, phân tích dữ liệu phòng thí nghiệm và viết bài báo khoa học', 'intro': 'Khoa học cơ bản là nền móng tri thức của toàn bộ nhân loại, khám phá các quy luật sâu thẳm nhất của vũ trụ, vật chất và tự nhiên. Những người làm khoa học cơ bản sở hữu tinh thần hoài nghi khoa học, lòng đam mê truy tìm chân lý tuyệt đối và phương pháp tư duy suy luận logic chặt chẽ - nguồn cội sinh ra mọi phát minh công nghệ vĩ đại.', 'beginner': 'Điều quan trọng nhất là rèn luyện phương pháp luận khoa học: luôn đặt câu hỏi nghiên cứu rõ ràng, thiết kế thí nghiệm có nhóm đối chứng (Control Group) và trình bày kết quả trung thực, chính xác.', 'tools': ['Phần mềm phân tích dữ liệu R / Python', 'LaTeX soạn thảo văn bản khoa học', 'Phần mềm thống kê đồ thị GraphPad Prism', 'Hệ thống quản lý tài liệu tham khảo Zotero'], 'standards': ['Quy chuẩn thiết kế thí nghiệm khoa học', 'Tiêu chuẩn trích dẫn và liêm chính học thuật', 'Quy tắc bình duyệt bài báo khoa học ngang hàng (Peer-review)', 'Đạo đức nghiên cứu khoa học cơ bản'], 'roles': {1: [('Thực tập sinh nghiên cứu khoa học cơ sở', 'Hỗ trợ thu thập tài liệu khoa học từ các tạp chí uy tín, nhập liệu số liệu thực nghiệm và hỗ trợ chuẩn bị mẫu.'), ('Trợ lý xử lý số liệu thống kê phòng lab', 'Tính toán giá trị trung bình, độ lệch chuẩn và kiểm tra tính phân phối chuẩn của tập dữ liệu thực nghiệm.'), ('Cộng tác viên soạn thảo báo cáo LaTeX', 'Chuyển đổi các công thức toán học và bảng biểu số liệu vào hệ thống soạn thảo văn bản khoa học LaTeX.')], 2: [('Nghiên cứu viên khoa học cơ bản tập sự', 'Chủ động tiến hành các đợt thí nghiệm kiểm chứng giả thuyết khoa học, phân tích phương sai ANOVA.'), ('Chuyên viên phân tích số liệu phòng thí nghiệm chuyên sâu', 'Sử dụng ngôn ngữ R hoặc GraphPad Prism để vẽ các biểu đồ phân bố, đường cong chuẩn và đánh giá ý nghĩa thống kê p-value.'), ('Trợ lý viết bài báo khoa học học thuật', 'Soạn thảo phần Phương pháp nghiên cứu và Kết quả thảo luận cho các bản thảo bài báo gửi đăng hội nghị.')]}}, 'Ngôn ngữ Trung Quốc': {'discipline': 'ngữ âm chuẩn, ngữ pháp căn bản, phản xạ giao tiếp thương mại, biên dịch tài liệu thương mại và giao tiếp liên văn hóa', 'intro': 'Ngôn ngữ Trung Quốc là cầu nối kinh tế và văn hóa chiến lược trong khu vực châu Á và toàn cầu. Khi quan hệ hợp tác thương mại, chuỗi cung ứng công nghiệp và đầu tư trực tiếp giữa Việt Nam và các nền kinh tế nói tiếng Hoa ngày càng phát triển mạnh mẽ, người sử dụng thành thạo tiếng Trung chuyên ngành thương mại là cầu nối không thể thay thế trong các tập đoàn sản xuất, xuất nhập khẩu và dịch vụ quốc tế.', 'beginner': 'Khó khăn lớn nhất của người mới học là hệ thống chữ Hán tượng hình và thanh điệu ngữ âm: phải kiên trì luyện viết chữ đúng quy tắc thứ tự nét, luyện phát âm chuẩn bảng Pinyin và luyện phản xạ nghe nói mỗi ngày.', 'tools': ['Phần mềm gõ chữ Hán Sogou Pinyin', 'Từ điển Pleco / Hanzii', 'Phần mềm hỗ trợ dịch thuật văn bản thương mại', 'Hệ thống luyện thi HSK trực tuyến'], 'standards': ['Khung tiêu chuẩn đánh giá năng lực tiếng Hán quốc tế (HSK 4/5/6 & HSKK)', 'Tiêu chuẩn phiên âm Pinyin quốc tế', 'Quy chuẩn thư tín thương mại tiếng Hoa', 'Nghi thức giao tiếp kinh doanh văn hóa Á Đông'], 'roles': {1: [('Cộng tác viên biên dịch tiếng Trung cơ bản', 'Dịch thuật tài liệu mô tả sản phẩm, phụ đề video ngắn và các bài viết tin tức thương mại đơn giản.'), ('Trợ lý giao dịch thương mại tiếng Trung', 'Hỗ trợ liên hệ nhà cung cấp Trung Quốc trên các sàn 1688, Taobao để hỏi giá và kiểm tra tồn kho.'), ('Cộng tác viên văn phòng công ty vốn FDI tiếng Hoa', 'Soạn thảo email giao dịch thông thường và hỗ trợ dịch các thông báo nội bộ đơn giản sang tiếng Việt.')], 2: [('Chuyên viên biên dịch tài liệu kỹ thuật & Thương mại', 'Dịch thuật hợp đồng mua bán ngoại thương, catalogue kỹ thuật máy móc và tài liệu quy trình sản xuất.'), ('Phiên dịch viên hiện trường nhà máy FDI', 'Phiên dịch trực tiếp giữa chuyên gia kỹ thuật người Hoa và công nhân vận hành máy trên xưởng sản xuất.'), ('Chuyên viên mua hàng quốc tế (Sourcing Executive)', 'Đàm phán giá cả, điều khoản giao hàng với các đối tác cung ứng nguyên liệu từ thị trường Trung Quốc, Đài Loan.')]}}, 'Xã hội học': {'discipline': 'phương pháp nghiên cứu định tính, kỹ thuật phỏng vấn sâu, khảo sát xã hội học, phương pháp nghiên cứu định lượng và viết báo cáo nghiên cứu', 'intro': 'Xã hội học là ngành khoa học nghiên cứu về quy luật hình thành, vận động và phát triển của các mối quan hệ xã hội, cơ cấu xã hội và các thiết chế văn hóa, cộng đồng. Các nhà xã hội học sở hữu năng lực nhìn thấu những vấn đề tiềm ẩn bên dưới bề mặt của đời sống: từ sự bất bình đẳng xã hội, biến đổi cấu trúc gia đình đến tác động của đô thị hóa và công nghệ đối với hành vi con người.', 'beginner': 'Sinh viên năm nhất cần học cách rèn luyện góc nhìn hoài nghi khoa học, gạt bỏ định kiến cá nhân và nắm chắc kỹ năng phỏng vấn sâu, lắng nghe chủ động để thu thập dữ liệu xã hội học chân thực.', 'tools': ['Phần mềm phân tích dữ liệu định tính NVivo / MAXQDA', 'Phần mềm phân tích định lượng SPSS', 'Bộ công cụ thiết kế khảo sát trực tuyến KoboToolbox', 'Sổ tay ghi chép điền dã'], 'standards': ['Quy tắc đạo đức nghiên cứu xã hội học (sự đồng thuận tự nguyện, bảo vệ danh tính)', 'Quy chuẩn thiết kế mẫu khảo sát ngẫu nhiên', 'Phương pháp luận phân tích nội dung (Content Analysis)', 'Tiêu chuẩn báo cáo đánh giá tác động xã hội (SIA)'], 'roles': {1: [('Điều tra viên khảo sát xã hội học cơ sở', 'Thực hiện phỏng vấn người dân theo bảng hỏi tại địa bàn dân cư và ghi chép nhật ký điền dã.'), ('Thực tập sinh gỡ băng phỏng vấn & Nhập liệu', 'Chuyển đổi các đoạn ghi âm phỏng vấn sâu thành văn bản chữ và nhập số liệu khảo sát vào phần mềm.'), ('Trợ lý dự án phát triển cộng đồng', 'Hỗ trợ công tác hậu cần, chuẩn bị tài liệu tập huấn và ghi biên bản các cuộc họp dân cư.')], 2: [('Chuyên viên phân tích dữ liệu xã hội học tập sự', 'Mã hóa dữ liệu định tính trên phần mềm NVivo và thực hiện chạy thống kê mô tả, tương quan trên SPSS.'), ('Cán bộ nghiên cứu & Đánh giá dự án (M&E Assistant)', 'Thu thập chỉ số đo lường hiệu quả của các dự án xã hội, lập báo cáo giám sát tiến độ thực hiện.'), ('Chuyên viên quan hệ cộng đồng & Trách nhiệm xã hội (CSR)', 'Khảo sát nhu cầu của cộng đồng địa phương và đề xuất các sáng kiến trách nhiệm xã hội cho doanh nghiệp.')]}}, 'Giáo dục học': {'discipline': 'tâm lý học lứa tuổi, giáo dục học đại cương, kỹ năng quản lý lớp học, xây dựng kế hoạch giảng dạy, phương pháp dạy học tích cực và đánh giá kết quả học tập', 'intro': 'Giáo dục học là nghệ thuật và khoa học khai phóng tiềm năng con người, truyền trao tri thức và bồi dưỡng nhân cách cho các thế hệ tương lai. Một nhà giáo hiện đại không còn là người độc thoại truyền thụ kiến thức một chiều mà là người thiết kế trải nghiệm học tập, ứng dụng công nghệ giáo dục (EdTech) và thắp lên ngọn lửa đam mê tự học suốt đời cho học sinh.', 'beginner': 'Người học sư phạm cần bắt đầu từ việc thấu hiểu tâm lý lứa tuổi học sinh, rèn luyện giọng nói truyền cảm, chuẩn mực chữ viết bảng và học cách xây dựng bầu không khí lớp học tích cực, an toàn và tôn trọng.', 'tools': ['Phần mềm thiết kế bài giảng tương tác Canva / PowerPoint / Genially', 'Nền tảng kiểm tra trực tuyến Kahoot / Quizizz', 'Hệ thống quản lý học tập LMS (Google Classroom, Canvas)', 'Bảng tương tác thông minh'], 'standards': ['Thang đo cấp độ tư duy Bloom (Nhớ - Hiểu - Vận dụng - Phân tích - Đánh giá - Sáng tạo)', 'Khung kế hoạch bài dạy chuẩn theo Công văn 5512 của Bộ GD&ĐT', 'Chuẩn nghề nghiệp giáo viên cơ sở giáo dục', 'Nguyên tắc đánh giá vì sự tiến bộ của người học'], 'roles': {1: [('Trợ giảng lớp học cơ sở (Teaching Assistant)', 'Hỗ trợ giáo viên điểm danh, chuẩn bị đồ dùng học tập, kiểm tra bài tập về nhà và ổn định trật tự lớp.'), ('Thực tập sinh thiết kế học liệu số', 'Thiết kế các slide bài giảng sinh động, phiếu bài tập trò chơi tương tác cho học sinh tiểu học hoặc THCS.'), ('Cộng tác viên tổ chức hoạt động trải nghiệm', 'Hỗ trợ điều phối các hoạt động ngoại khóa, câu lạc bộ khoa học và trò chơi rèn luyện kỹ năng sống.')], 2: [('Giáo viên tập sự / Giáo viên kỹ năng sống', 'Trực tiếp giảng dạy các chuyên đề kỹ năng sống, tổ chức các hoạt động học tập nhóm trên lớp học thực tế.'), ('Chuyên viên phát triển nội dung giáo dục số (EdTech Content)', 'Biên soạn kịch bản video bài giảng trực tuyến, xây dựng ngân hàng câu hỏi trắc nghiệm tương tác.'), ('Chuyên viên khảo thí & Đánh giá chất lượng giáo dục', 'Xây dựng ma trận đề kiểm tra đánh giá năng lực học sinh theo chuẩn đầu ra và thống kê phân tích phổ điểm.')]}}, 'Nông học': {'discipline': 'sinh học nông nghiệp, thiết kế thí nghiệm đồng ruộng, phân tích số liệu mùa vụ trên Excel, quản lý sản xuất nông nghiệp công nghệ cao và đánh giá chất lượng đất', 'intro': 'Nông học hiện đại là ngành khoa học ứng dụng công nghệ sinh học, cảm biến thông minh và kỹ thuật canh tác bền vững để sản xuất lương thực an toàn, năng suất cao và thích ứng với biến đổi khí hậu. Rời xa hình ảnh người nông dân chân lấm tay bùn truyền thống, kỹ sư nông học ngày nay là những nhà quản lý nông nghiệp thông minh, điều hành các hệ thống nhà màng tự động, điều khiển dinh dưỡng cây trồng bằng máy tính và bảo vệ sức khỏe đất.', 'beginner': 'Sinh viên năm nhất cần học cách quan sát tỉ mỉ hình thái cây trồng, hiểu rõ chu kỳ sinh trưởng và nắm vững các phương pháp bố trí thí nghiệm đồng ruộng có lặp lại để thu thập số liệu chuẩn xác.', 'tools': ['Bộ kit kiểm tra nhanh pH, độ dẫn điện EC và dinh dưỡng N-P-K trong đất', 'Máy đo chỉ số diệp lục SPAD', 'Microsoft Excel phân tích số liệu mùa vụ', 'Hệ thống điều khiển tưới nhỏ giọt tự động Israel'], 'standards': ['Tiêu chuẩn thực hành nông nghiệp tốt Việt Nam (VietGAP) & Toàn cầu (GlobalGAP)', 'Quy chuẩn kỹ thuật quốc gia về chất lượng đất nông nghiệp QCVN', 'Tiêu chuẩn canh tác nông nghiệp hữu cơ TCVN 11041', 'Quy trình khảo nghiệm giống cây trồng'], 'roles': {1: [('Kỹ thuật viên thực nghiệm đồng ruộng cơ sở', 'Gieo trồng, theo dõi tỷ lệ nảy mầm, đo đạc các chỉ tiêu sinh trưởng (chiều cao cây, đường kính thân) tại trại thực nghiệm.'), ('Thực tập sinh phân tích mẫu đất và nước tưới', 'Lấy mẫu đất đại diện ngoài đồng ruộng, sấy khô, nghiền mẫu và đo chỉ số pH, EC bằng máy đo chuyên dụng.'), ('Cộng tác viên bảo vệ thực vật', 'Quan sát phát hiện sớm các ổ dịch sâu bệnh hại trên cây trồng và ghi chép nhật ký nông hộ.')], 2: [('Kỹ sư quản lý nhà màng nông nghiệp công nghệ cao', 'Vận hành hệ thống châm phân tự động qua đường ống tưới nhỏ giọt, điều chỉnh quạt thông gió và lưới cắt nắng.'), ('Chuyên viên tư vấn kỹ thuật nông nghiệp (Agri Technical Advisor)', 'Tư vấn cho trang trại về lịch bón phân cân đối, sử dụng thuốc bảo vệ thực vật sinh học an toàn theo nguyên tắc 4 đúng.'), ('Kỹ sư giám sát tiêu chuẩn VietGAP/GlobalGAP', 'Thiết lập và giám sát việc ghi chép nhật ký sản xuất truy xuất nguồn gốc nông sản phục vụ cấp chứng nhận xuất khẩu.')]}}, 'Y khoa': {'discipline': 'giải phẫu - sinh lý người đại cương, kiểm soát nhiễm khuẩn bệnh viện, đọc hiểu tài liệu y khoa quốc tế, giao tiếp ứng xử với người bệnh và quản lý hồ sơ bệnh án điện tử', 'intro': "Ngành Y khoa là sứ mệnh thiêng liêng bảo vệ và chăm sóc sức khỏe, sinh mạng con người. Để khoác lên mình chiếc áo blouse trắng cao quý, người thầy thuốc tương lai phải trải qua quá trình khổ luyện phi thường về mặt tri thức khoa học chính xác, sự vững vàng của đôi bàn tay lâm sàng và trên hết là trái tim nhân ái, y đức sáng ngời 'Lương y như từ mẫu'.", 'beginner': 'Nền tảng của người học y là sự thấu hiểu tường tận cấu trúc cơ thể người từ môn Giải phẫu học, ghi nhớ chính xác thuật ngữ y khoa quốc tế và tuyệt đối tuân thủ quy trình kiểm soát nhiễm khuẩn vô khuẩn bệnh viện.', 'tools': ['Mô hình giải phẫu người 3D & Phần mềm Complete Anatomy', 'Ống nghe y tế (Littmann) & Máy đo huyết áp cơ', 'Cơ sở dữ liệu y văn quốc tế PubMed / UpToDate', 'Phần mềm quản lý bệnh viện & Bệnh án điện tử HIS/EMR'], 'standards': ['Lời thề Hippocrates và 12 điều Y đức của Bộ Y tế', 'Quy chuẩn vô khuẩn và kiểm soát nhiễm khuẩn bệnh viện của WHO', 'Tiêu chuẩn ghi chép hồ sơ bệnh án theo quy định pháp luật', 'Hướng dẫn chẩn đoán và điều trị của Bộ Y tế'], 'roles': {1: [('Sinh viên thực tập điều dưỡng & Chăm sóc cơ bản', 'Hỗ trợ đo dấu hiệu sinh tồn (mạch, nhiệt độ, huyết áp, nhịp thở), vệ sinh cá nhân và hỗ trợ di chuyển bệnh nhân.'), ('Trợ lý phòng thực hành giải phẫu', 'Bảo quản mô hình giải phẫu, hỗ trợ chuẩn bị tiêu bản giải phẫu bệnh và hướng dẫn nhóm học tập tra cứu.'), ('Tình nguyện viên tư vấn sức khỏe cộng đồng', 'Tham gia các chiến dịch hiến máu tình nguyện, tuyên truyền vệ sinh phòng dịch tại địa bàn dân cư.')], 2: [('Sinh viên thực tập lâm sàng bệnh viện', 'Tiếp xúc hỏi bệnh sử, khám thực thể các cơ quan dưới sự giám sát trực tiếp của bác sĩ giảng viên lâm sàng.'), ('Chuyên viên quản lý hồ sơ bệnh án điện tử (EMR Trainee)', 'Nhập liệu chẩn đoán theo mã bệnh quốc tế ICD-10 và tra cứu lịch sử xét nghiệm trên phần mềm HIS.'), ('Trợ lý nghiên cứu thử nghiệm lâm sàng', 'Hỗ trợ theo dõi các tiêu chí đánh giá sức khỏe bệnh nhân tham gia các đề tài nghiên cứu y học lâm sàng.')]}}, 'Quản trị khách sạn': {'discipline': 'tổng quan ngành du lịch - khách sạn, tiêu chuẩn dịch vụ khách hàng 5 sao, tiếng Anh chuyên ngành, nghiệp vụ lễ tân - buồng phòng và kỹ năng xử lý khiếu nại', 'intro': 'Quản trị khách sạn và Du lịch là nghệ thuật mến khách (Hospitality), nơi nụ cười ấm áp, sự tinh tế trong từng chi tiết phục vụ và đẳng cấp dịch vụ chuẩn mực quốc tế tạo nên những kỷ niệm khó quên cho du khách. Trong ngành công nghiệp không khói đầy tiềm năng này, người quản trị khách sạn thành công là người có năng lực bao quát mọi nghiệp vụ tiền sảnh, ẩm thực và buồng phòng, đồng thời sở hữu nghệ thuật xử lý tình huống khéo léo.', 'beginner': 'Người mới bắt đầu cần rèn luyện tác phong diện mạo chuẩn mực (Grooming), thái độ niềm nở chu đáo và kỹ năng giao tiếp tiếng Anh lưu loát trong mọi tình huống đón tiếp khách.', 'tools': ['Hệ thống quản lý khách sạn PMS (Opera / Smile / eZee)', 'Phần mềm đặt phòng trực tuyến OTA Extranet', 'Bộ dụng cụ chuẩn bị tiệc và phòng mẫu', 'Bộ đàm nội bộ khách sạn'], 'standards': ['Tiêu chuẩn kỹ năng nghề du lịch Việt Nam (VTOS)', 'Tiêu chuẩn phân hạng khách sạn 5 sao TCVN 4391', 'Quy trình xử lý khiếu nại khách hàng theo phương pháp LAST', 'Quy chuẩn an toàn vệ sinh thực phẩm và phòng cháy khách sạn'], 'roles': {1: [('Nhân viên hỗ trợ hành lý & Đón tiếp (Bellman / Doorman Intern)', 'Chào đón khách tại cửa sảnh, hỗ trợ vận chuyển hành lý lên phòng và hướng dẫn khách các tiện ích cơ bản.'), ('Thực tập sinh buồng phòng (Housekeeping Trainee)', 'Thực hành dọn phòng khách theo quy trình tiêu chuẩn 5 sao: thay ga gối, bổ sung đồ dùng amenities và kiểm tra vệ sinh.'), ('Nhân viên phục vụ tiệc và nhà hàng (F&B Attendant)', 'Sắp xếp bàn ăn theo chuẩn Âu/Á, bưng bê phục vụ đồ ăn thức uống và dọn dẹp sau tiệc.')], 2: [('Nhân viên lễ tân khách sạn chuyên nghiệp (Front Desk Agent)', 'Thực hiện quy trình check-in, check-out trên phần mềm PMS, đổi tiền tệ và cung cấp thông tin du lịch cho khách.'), ('Chuyên viên chăm sóc khách hàng VIP (Guest Relations Officer)', 'Đón tiếp các khách hàng đặc biệt, ghi nhận sở thích cá nhân và chuẩn bị quà tặng chào mừng chu đáo.'), ('Nhân viên đặt phòng (Reservations Agent)', 'Tiếp nhận các yêu cầu đặt phòng qua email, điện thoại và cập nhật tình trạng phòng trống lên các kênh OTA.')]}}, 'Truyền thông': {'discipline': 'nguyên lý truyền thông đại chúng, sáng tạo nội dung đa nền tảng, viết và trình bày bài viết, chiến lược quan hệ công chúng PR và quản trị thương hiệu', 'intro': 'Truyền thông và Báo chí là chiếc gương phản chiếu nhịp đập xã hội và là công cụ mạnh mẽ nhất định hình dư luận công chúng và xây dựng niềm tin thương hiệu. Một người làm truyền thông hiện đại cần sở hữu ngòi bút nhạy bén, tư duy thông tin đa chiều, đạo đức báo chí trung thực và năng lực hoạch định các chiến dịch quan hệ công chúng (PR) có sức lay động lòng người.', 'beginner': 'Sinh viên năm nhất cần bắt đầu từ việc rèn giũa kỹ năng viết tiếng Việt chuẩn xác, mạch lạc, không dùng từ sáo rỗng, và rèn luyện thói quen kiểm chứng nguồn tin trước khi đưa tin.', 'tools': ['Phần mềm biên tập văn bản', 'Máy ghi âm chuyên dụng & Máy ảnh', 'Phần mềm theo dõi thông tin báo chí (Social Listening Tools)', 'Hệ thống quản lý nội dung CMS'], 'standards': ['Luật Báo chí và 10 điều Quy định đạo đức nghề nghiệp người làm báo Việt Nam', 'Cấu trúc tin bài hình tháp ngược (Inverted Pyramid)', 'Khung kế hoạch quan hệ công chúng RACE / ROSTIR', 'Quy trình xử lý khủng hoảng truyền thông'], 'roles': {1: [('Cộng tác viên viết bài tin tức & Phóng sự ngắn', 'Tìm kiếm đề tài đời sống, thực hiện phỏng vấn nhân chứng và viết tin bài theo cấu trúc hình tháp ngược.'), ('Thực tập sinh quản trị nội dung Fanpage truyền thông', 'Lên lịch đăng bài, biên tập hình ảnh và trả lời bình luận của độc giả trên các kênh mạng xã hội.'), ('Trợ lý sự kiện báo chí & Họp báo', 'Chuẩn bị tài liệu thông cáo báo chí (Press Kit), tiếp đón phóng viên và hỗ trợ ghi âm cuộc họp báo.')], 2: [('Chuyên viên quan hệ công chúng tập sự (Junior PR Executive)', 'Soạn thảo thông cáo báo chí, duy trì danh bạ quan hệ báo chí và theo dõi độ phủ sóng truyền thông (Media Clipping).'), ('Phóng viên ảnh / Phóng viên truyền hình số', 'Tác nghiệp tại hiện trường, quay các đoạn phóng sự ngắn và dựng video tin tức phát sóng trên nền tảng số.'), ('Chuyên viên xử lý truyền thông nội bộ', 'Sản xuất tạp chí nội bộ, bản tin radio doanh nghiệp và lan tỏa các giá trị văn hóa tổ chức.')]}}}
